/**
 * Curve25519 Base Field Arithmetic — Concrete Implementation
 *
 * This module provides the constant-operation-count implementations of all
 * modular arithmetic operations over the Curve25519 prime field GF(p), where:
 * ```
 * p = 2^255 - 19
 *   = 57896044618658097711785492504343953926634992332820282019728792003956564819949
 * ```
 *
 * ## Role in the SDK
 *
 * This module is the lowest-level arithmetic layer in the SDK's cryptographic
 * stack. Its exported functions are consumed by:
 *
 * - **`crypto/rescue-cipher/`** — the Rescue-XLIX block cipher used inside
 *   Arcium MPC computations for symmetric encryption of Umbra confidential
 *   token account balances.
 * - **`math/curve25519/interfaces`** — the function-type contracts that the
 *   exported symbols satisfy.
 * - Dependency-injection consumers that call
 *   `getCurve25519FieldElementSampler` with custom arithmetic.
 *
 * X25519 key-exchange itself (used for Umbra encrypted token account key
 * registration) does not call this module directly — its scalar multiplication
 * is handled by `@noble/curves` — but the field prime is the same.
 *
 * ## Algorithm Overview
 *
 * ### Addition / Subtraction
 *
 * Both operations are implemented at the 4-limb level using carry/borrow
 * propagation, followed by a **constant-time conditional correction**:
 *
 * - **Addition**: compute `t = a + b`; if `t ≥ p` then return `t - p`, else `t`.
 *   The conditional is resolved by a bitwise mask derived from the carry and
 *   borrow, never an `if` statement.
 * - **Subtraction**: compute `d = a - b`; if a borrow occurred (a < b), add `p`
 *   back. The borrow bit is propagated as a mask applied to `P_LIMBS`.
 *
 * ### Multiplication
 *
 * Uses JavaScript's native `BigInt` multiplication (`a * b`) followed by
 * a single `% p` reduction. While this is not a limb-level schoolbook
 * implementation, `BigInt` intermediate values of ≤ 510 bits keep the
 * per-call work uniform. Montgomery form is not used because the constant
 * conversion overhead is not amortised over the small number of multiplications
 * per Rescue-XLIX round.
 *
 * ### Inversion
 *
 * Uses Fermat's Little Theorem: `a^(-1) ≡ a^(p-2) (mod p)`. This delegates to
 * the square-and-multiply exponentiation function with a fixed exponent of
 * p - 2 ≈ 2^255, costing ≈ 255 squarings and ~128 multiplications.
 *
 * ### Exponentiation
 *
 * Binary (square-and-multiply) exponentiation via `moduleExpLimbs`. The loop
 * visits each bit of the exponent from LSB to MSB; the branch on the current
 * bit (`exp & 1n`) operates on the **exponent**, not secret field data, so it
 * does not constitute a secret-dependent branch.
 *
 * ## Security Considerations
 *
 * True hardware-level constant time cannot be guaranteed in JavaScript because
 * the V8/SpiderMonkey JIT, branch predictors, and GC can all introduce
 * data-dependent timing variation. These implementations are
 * **constant-operation-count**: they always execute the same sequence of BigInt
 * operations regardless of the input values. This is the accepted standard for
 * JavaScript cryptographic libraries (e.g., `@noble/curves`).
 *
 * Secret-dependent branching is avoided by:
 * - Using `ctSelect` (bitwise mask) for all conditional value choices.
 * - Processing all 4 limbs in every loop iteration regardless of value.
 * - Applying `P_LIMBS` correction via masking rather than a conditional add.
 *
 * ## Limb Representation
 *
 * All internal computation decomposes field elements into four 64-bit limbs
 * stored in little-endian order `[limb0, limb1, limb2, limb3]`:
 * ```
 * value = limb0 + limb1×2^64 + limb2×2^128 + limb3×2^192
 * ```
 * - `limb0` — bits 0-63 (least significant)
 * - `limb1` — bits 64-127
 * - `limb2` — bits 128-191
 * - `limb3` — bits 192-255 (most significant; high bit always 0 for valid elements)
 *
 * The 4-limb split keeps individual BigInt values at a uniform 64-bit size,
 * making per-limb arithmetic cost independent of the field element's magnitude.
 *
 * @module implementation/mathematics/curve25519-field-arithmetic
 * @packageDocumentation
 */

import type {
  Curve25519FieldElementLimb,
  Curve25519ModuloAddFunction as Curve25519ModuleAddFunction,
  Curve25519ModuloInvFunction as Curve25519ModuleInvFunction,
  Curve25519ModuloMulFunction as Curve25519ModuleMulFunction,
  Curve25519ModuloPowFunction as Curve25519ModulePowFunction,
  Curve25519ModuloSubFunction as Curve25519ModuleSubFunction,
  U512BasedCurve25519FieldElementSamplerFunction as U512BasedCurve25519FieldElementSamplerFunction,
  U512BasedCurve25519FieldElementSamplerDeps,
} from "./interfaces";
import { CURVE25519_FIELD_PRIME, type Curve25519FieldElement } from "./types";
import { type U512BeBytes, U256_BYTE_LENGTH } from "../../common/types";
import { createU256BeBytes } from "../../common/converters/branded";
import { decodeU256BeBytesToU256 } from "../../common/converters/mathematics";

// =============================================================================
// Constants
// =============================================================================

/**
 * The number of bits per limb used in the 4-limb field element representation.
 *
 * @remarks
 * All field elements are decomposed into 4 limbs of exactly 64 bits each.
 * Using 64 as the limb width keeps each limb within the range of a single
 * 64-bit unsigned integer, making carry/borrow arithmetic straightforward
 * with BigInt shift operations.
 *
 * @internal
 */
const N64 = 64n;

/**
 * Bitmask for extracting the lower 64 bits from a BigInt.
 *
 * @remarks
 * Equal to 2^64 - 1 = 0xFFFFFFFFFFFFFFFF. Applied with the bitwise AND
 * operator (`& MASK64`) after any addition or shift to isolate the low 64
 * bits of a result and discard any carry that has propagated into bit 64 or
 * above.
 *
 * @example
 * ```typescript
 * // Extract low 64 bits after an addition that may overflow
 * const sum = a + b + carry;
 * const low64 = sum & MASK64;      // keep bits 0-63
 * const nextCarry = sum >> N64;    // propagate bit 64 upwards
 * ```
 *
 * @internal
 */
const MASK64 = 0xff_ff_ff_ff_ff_ff_ff_ffn;

/**
 * The Curve25519 field prime p = 2^255 - 19 decomposed into 4 × 64-bit limbs,
 * stored in little-endian order.
 *
 * @remarks
 * Binary representation of p = 2^255 - 19:
 * - Bits 0-63:   `0xFFFFFFFFFFFFFFED` (= 2^64 - 19)
 * - Bits 64-127: `0xFFFFFFFFFFFFFFFF` (all ones)
 * - Bits 128-191:`0xFFFFFFFFFFFFFFFF` (all ones)
 * - Bits 192-255:`0x7FFFFFFFFFFFFFFF` (2^63 - 1; high bit is 0)
 *
 * The high bit of limb 3 being 0 reflects the fact that p < 2^255.
 *
 * This constant is used in:
 * - `addModuleLimbs` — trial subtraction to enforce the canonical range.
 * - `subModuleLimbs` — conditional addition to wrap negative differences.
 * - `reduce256Curve25519` — single-step reduction of 256-bit values.
 *
 * @privateRemarks
 * Limb 0 value derivation:
 * p = 2^255 - 19.  The low 64 bits of p are:
 * 2^64 × floor(p / 2^64) + r  =>  r = p mod 2^64 = (2^64 - 19) = 0xFFFFFFFFFFFFFFED
 *
 * @internal
 */
const P_LIMBS: Curve25519FieldElementLimb = [
  0xff_ff_ff_ff_ff_ff_ff_edn, // limb 0 (bits 0-63): 2^64 - 19
  0xff_ff_ff_ff_ff_ff_ff_ffn, // limb 1 (bits 64-127): all 1s
  0xff_ff_ff_ff_ff_ff_ff_ffn, // limb 2 (bits 128-191): all 1s
  0x7f_ff_ff_ff_ff_ff_ff_ffn, // limb 3 (bits 192-255): 2^63 - 1
];

// =============================================================================
// Internal Helper Functions
// =============================================================================

/**
 * Constant-time conditional select between two `bigint` values.
 *
 * @remarks
 * Returns `x` when `bit === 1n` and `y` when `bit === 0n`, without branching
 * on the value of `bit`. The selection is performed using bitwise arithmetic:
 * ```
 * mask = -bit      // 0n if bit=0, -1n (all ones) if bit=1
 * result = (x & mask) | (y & ~mask)
 * ```
 * This is the BigInt equivalent of the C idiom `(mask & x) | (~mask & y)`.
 *
 * `bit` MUST be exactly `0n` or `1n`. Passing any other value produces
 * undefined results.
 *
 * @param bit - Selection bit. Must be `0n` or `1n`.
 * @param x - Value returned when `bit === 1n`.
 * @param y - Value returned when `bit === 0n`.
 * @returns `x` if `bit === 1n`; `y` if `bit === 0n`.
 *
 * @privateRemarks
 * JavaScript BigInt negation of a 1-bit value: `-1n` in BigInt is the
 * two's-complement all-ones pattern (arbitrary precision), which acts as a
 * perfect mask. `-0n === 0n`, so the 0 case also works correctly.
 *
 * @internal
 */
function ctSelect(bit: bigint, x: bigint, y: bigint): bigint {
  const mask = -bit;
  return (x & mask) | (y & ~mask);
}

/**
 * Decomposes a non-negative `bigint` into the 4-limb little-endian representation
 * used throughout this module.
 *
 * @remarks
 * Extracts four 64-bit windows by successive right-shifts combined with
 * `MASK64`:
 * ```
 * limb0 = value              & 0xFFFFFFFFFFFFFFFF  (bits 0-63)
 * limb1 = (value >> 64)      & 0xFFFFFFFFFFFFFFFF  (bits 64-127)
 * limb2 = (value >> 128)     & 0xFFFFFFFFFFFFFFFF  (bits 128-191)
 * limb3 = (value >> 192)     & 0xFFFFFFFFFFFFFFFF  (bits 192-255)
 * ```
 *
 * The input must satisfy 0 ≤ value < 2^256. Values in the range [p, 2^256)
 * are representable in limb form but are not canonical field elements;
 * callers are responsible for reducing them if needed.
 *
 * @param value - A non-negative `bigint` in range [0, 2^256 - 1].
 * @returns A 4-element tuple `[limb0, limb1, limb2, limb3]` in little-endian order.
 *
 * @internal
 */
function bigintToLimbs(value: bigint): Curve25519FieldElementLimb {
  return [
    value & MASK64,
    (value >> N64) & MASK64,
    (value >> (N64 * 2n)) & MASK64,
    (value >> (N64 * 3n)) & MASK64,
  ];
}

/**
 * Reconstructs a `bigint` from the 4-limb little-endian representation.
 *
 * @remarks
 * Computes:
 * ```
 * value = limbs[0]
 *       + limbs[1] × 2^64
 *       + limbs[2] × 2^128
 *       + limbs[3] × 2^192
 * ```
 *
 * This is the inverse of {@link bigintToLimbs}. The reconstructed value lies in
 * [0, 2^256 - 1] (or [0, p-1] if the limbs represent a canonical field element).
 *
 * @param limbs - A 4-element tuple in little-endian order, each limb in [0, 2^64 - 1].
 * @returns The reconstructed `bigint` value.
 *
 * @internal
 */
function limbsToBigint(limbs: Curve25519FieldElementLimb): bigint {
  return limbs[0] + (limbs[1] << N64) + (limbs[2] << (N64 * 2n)) + (limbs[3] << (N64 * 3n));
}

/**
 * Constant-time modular addition of two field elements, both in 4-limb form.
 *
 * @remarks
 * ## Algorithm
 *
 * **Step 1 — Raw addition with carry propagation:**
 * ```
 * t[i] = a[i] + b[i] + carry_in
 * t_carry = final carry out of limb 3
 * ```
 * The carry is propagated upward through all 4 limbs. After all limbs are
 * processed, `tCarry` is `1n` iff the sum `a + b` exceeded 2^256 - 1.
 *
 * **Step 2 — Trial subtraction:**
 * ```
 * d = t - p   (with borrow propagation across 4 limbs)
 * ```
 * After this step, `borrow` is `1n` iff `t < p` (i.e., no reduction needed).
 *
 * **Step 3 — Constant-time selection:**
 * ```
 * useD = tCarry | (1 - borrow)
 * result[i] = ctSelect(useD, d[i], t[i])
 * ```
 * If `tCarry` is 1 (overflow) or if the trial subtraction did not borrow
 * (meaning t ≥ p), use the reduced value `d`. Otherwise use `t`.
 *
 * No `if` statement branches on input-derived data.
 *
 * @param a - Minuend in 4-limb form. Each limb in [0, 2^64 - 1]; value in [0, p-1].
 * @param b - Subtrahend in 4-limb form. Each limb in [0, 2^64 - 1]; value in [0, p-1].
 * @returns The canonical sum `(a + b) mod p` in 4-limb form.
 *
 * @internal
 */
function addModuleLimbs(
  a: Curve25519FieldElementLimb,
  b: Curve25519FieldElementLimb,
): Curve25519FieldElementLimb {
  // 1. Raw Addition: t = a + b
  const t: bigint[] = [0n, 0n, 0n, 0n];
  let carry = 0n;

  for (let index = 0; index < 4; index++) {
    const sum = a[index] + b[index] + carry;
    t[index] = sum & MASK64;
    carry = sum >> N64;
  }
  const tCarry = carry;

  // 2. Trial Subtraction: d = t - p
  const d: bigint[] = [0n, 0n, 0n, 0n];
  let borrow = 0n;

  for (let index = 0; index < 4; index++) {
    const sub = t[index] - P_LIMBS[index] - borrow;
    d[index] = sub & MASK64;
    borrow = -(sub >> N64);
  }

  // 3. Selection: use d if overflow or no borrow
  const useD = tCarry | (1n - borrow);

  return [
    ctSelect(useD, d[0], t[0]),
    ctSelect(useD, d[1], t[1]),
    ctSelect(useD, d[2], t[2]),
    ctSelect(useD, d[3], t[3]),
  ];
}

/**
 * Constant-time modular subtraction of two field elements, both in 4-limb form.
 *
 * @remarks
 * ## Algorithm
 *
 * **Step 1 — Raw subtraction with borrow propagation:**
 * ```
 * out[i] = a[i] - b[i] - borrow_in
 * ```
 * After all 4 limbs, `borrow` is `1n` iff a < b (the difference is negative
 * in ordinary arithmetic and must wrap around modulo p).
 *
 * **Step 2 — Conditional add-back of p:**
 * ```
 * mask = -borrow   // all-ones mask if a < b, zero mask otherwise
 * for each limb i:
 *   addValue = P_LIMBS[i] & mask   // add p iff borrow occurred
 *   out[i] = out[i] + addValue + carry
 * ```
 * The mask is derived from the borrow bit without a branch. When borrow = 0
 * the mask is 0 and no correction is applied. When borrow = 1 the mask is
 * all-ones and p is added back.
 *
 * @param a - Minuend in 4-limb form. Value in [0, p-1].
 * @param b - Subtrahend in 4-limb form. Value in [0, p-1].
 * @returns The canonical difference `(a - b) mod p` in 4-limb form.
 *
 * @internal
 */
function subModuleLimbs(
  a: Curve25519FieldElementLimb,
  b: Curve25519FieldElementLimb,
): Curve25519FieldElementLimb {
  // 1. Calculate diff = a - b
  const out: bigint[] = [0n, 0n, 0n, 0n];
  let borrow = 0n;

  for (let index = 0; index < 4; index++) {
    const sub = a[index] - b[index] - borrow;
    out[index] = sub & MASK64;
    borrow = -(sub >> N64);
  }

  // 2. If we borrowed, add P back using masking
  const mask = -borrow;
  let carry = 0n;

  for (let index = 0; index < 4; index++) {
    const addValue = P_LIMBS[index] & mask;

    const sum = out[index] + addValue + carry;
    out[index] = sum & MASK64;
    carry = sum >> N64;
  }

  return [out[0], out[1], out[2], out[3]];
}

/**
 * Modular multiplication of two field elements in 4-limb form, returning the
 * product reduced modulo p.
 *
 * @remarks
 * ## Algorithm
 *
 * Converts both limb arrays back to full-precision `BigInt` values, performs
 * native `BigInt` multiplication to obtain a ≤ 510-bit intermediate product,
 * and reduces by `% CURVE25519_FIELD_PRIME`.
 *
 * ```
 * product = limbsToBigint(a) * limbsToBigint(b)  (up to 510 bits)
 * reduced = product % p
 * return bigintToLimbs(reduced)
 * ```
 *
 * ## Why Not Schoolbook Limb Multiplication?
 *
 * A true 4×4 schoolbook multiplication would produce an 8-limb (512-bit)
 * intermediate and require a multi-step reduction using the structure of p.
 * JavaScript's `BigInt` already implements this internally, and the V8 engine
 * performs the reduction in native code. This approach is simpler and has
 * predictable worst-case cost.
 *
 * ## Why Not Montgomery Form?
 *
 * Montgomery multiplication eliminates the per-call division at the cost of
 * converting inputs into and out of Montgomery domain. That conversion
 * overhead is only amortized when the same operands participate in many
 * multiplications (e.g., long scalar multiplication chains). For the Rescue
 * cipher's relatively short permutation rounds, the conversion cost is not
 * justified.
 *
 * @param a - First factor in 4-limb form. Value in [0, p-1].
 * @param b - Second factor in 4-limb form. Value in [0, p-1].
 * @returns The canonical product `(a × b) mod p` in 4-limb form.
 *
 * @internal
 */
function mulModuleLimbs(
  a: Curve25519FieldElementLimb,
  b: Curve25519FieldElementLimb,
): Curve25519FieldElementLimb {
  // For Curve25519, we use direct multiplication and reduction
  // This is simpler than Montgomery for this specific prime
  const aBig = limbsToBigint(a);
  const bBig = limbsToBigint(b);
  const product = (aBig * bBig) % CURVE25519_FIELD_PRIME;
  return bigintToLimbs(product);
}

/**
 * Modular exponentiation of a field element by an arbitrary non-negative
 * exponent, using binary square-and-multiply.
 *
 * @remarks
 * ## Algorithm — Binary Exponentiation
 *
 * Starting from `result = 1` (the multiplicative identity in limb form):
 * ```
 * current = base
 * while exp > 0:
 *   if (exp & 1) == 1:
 *     result = result × current   (mod p)
 *   current = current × current  (mod p)
 *   exp >>= 1
 * return result
 * ```
 *
 * The branch `if (exp & 1) == 1` tests a bit of the **exponent**, not a
 * secret field value. When the exponent is a fixed protocol constant (e.g.,
 * p - 2 for inversion) this does not leak secret data; when the exponent is
 * secret (e.g., a private scalar), a constant-time double-and-add should be
 * used instead.
 *
 * ## Cost
 *
 * For an n-bit exponent: at most n squarings and at most n multiplications
 * (≈ n/2 on average). For the full range [0, p-1] this is ≈ 255 squarings
 * and ≈ 128 multiplications.
 *
 * @param base - Base field element in 4-limb form. Value in [0, p-1].
 * @param exp - Non-negative exponent as a plain `bigint`.
 * @returns `base^exp mod p` in 4-limb form.
 *
 * @internal
 */
function moduleExpLimbs(base: Curve25519FieldElementLimb, exp: bigint): Curve25519FieldElementLimb {
  let result: Curve25519FieldElementLimb = [1n, 0n, 0n, 0n];
  let current = base;

  while (exp > 0n) {
    if ((exp & 1n) === 1n) {
      result = mulModuleLimbs(result, current);
    }
    current = mulModuleLimbs(current, current);
    exp >>= 1n;
  }

  return result;
}

