// =============================================================================
// U512-Based Field Element Sampler
// =============================================================================

/**
 * The Montgomery constant R = 2^256 mod p for the Curve25519 field.
 *
 * @remarks
 * Used in the U512-based sampler to combine the high and low 256-bit halves
 * of a 512-bit input into a single field element:
 * ```
 * result = (high × R + low)  mod p
 * ```
 *
 * ## Derivation
 *
 * ```
 * 2^256 = 2 × 2^255
 *       = 2 × (p + 19)       (since p = 2^255 - 19)
 *       = 2p + 38
 * ∴ 2^256 mod p = 38
 * ```
 *
 * The small value of R (just 38) means the multiplication `high × R` can be
 * computed cheaply: it is equivalent to `high × 38`, well within the range
 * of a single BigInt multiply-and-reduce.
 *
 * @internal
 */
const R_MOD_P_CURVE25519 = 38n;

/**
 * Reduces a 256-bit value into the canonical Curve25519 field range [0, p)
 * using constant-time trial subtraction.
 *
 * @remarks
 * ## Algorithm
 *
 * Computes `d = value - p` using 4-limb borrow propagation. If the final
 * borrow is 1, then value < p and the original value should be returned;
 * otherwise d is in [0, p) and should be returned. Selection between `value`
 * and `d` is performed with {@link ctSelect} — no branch on the borrow bit.
 *
 * This function handles exactly one conditional subtraction, which is correct
 * because the input is guaranteed to be in [0, 2^256). Any value in
 * [p, 2^256) satisfies p ≤ value < 2p (since p > 2^254), so a single
 * subtraction of p suffices.
 *
 * @param value - A non-negative `bigint` in [0, 2^256 - 1]. Values already
 *   in [0, p) are returned unchanged. Values in [p, 2^256) are reduced by p.
 * @returns The equivalent element in the canonical range [0, p-1].
 *
 * @internal
 */
function reduce256Curve25519(value: bigint): bigint {
  const [l0, l1, l2, l3] = bigintToLimbs(value);
  const [p0, p1, p2, p3] = P_LIMBS;

  // Trial subtraction: d = value - p
  // Compute d0
  const sub0 = l0 - p0;
  const d0 = sub0 & MASK64;
  const borrow0 = -(sub0 >> N64) & 1n;

  // Compute d1
  const sub1 = l1 - p1 - borrow0;
  const d1 = sub1 & MASK64;
  const borrow1 = -(sub1 >> N64) & 1n;

  // Compute d2
  const sub2 = l2 - p2 - borrow1;
  const d2 = sub2 & MASK64;
  const borrow2 = -(sub2 >> N64) & 1n;

  // Compute d3
  const sub3 = l3 - p3 - borrow2;
  const d3 = sub3 & MASK64;
  const borrow3 = -(sub3 >> N64) & 1n;

  // If borrow3 is 0, value >= p, so use d (the subtracted value)
  // If borrow3 is 1, value < p, so use original value
  const useOriginal = borrow3;

  return limbsToBigint([
    ctSelect(useOriginal, l0, d0),
    ctSelect(useOriginal, l1, d1),
    ctSelect(useOriginal, l2, d2),
    ctSelect(useOriginal, l3, d3),
  ]);
}

/**
 * Decodes 32 bytes from a big-endian byte array starting at `offset` into a
 * `bigint`, using the SDK's typed `U256BeBytes` converter pipeline.
 *
 * @remarks
 * Steps:
 * 1. Slice `bytes[offset .. offset+32]` (32 bytes = 256 bits).
 * 2. Wrap the slice in a `U256BeBytes` branded type via `createU256BeBytes`.
 * 3. Decode the branded bytes to a `bigint` via `decodeU256BeBytesToU256`.
 *
 * The resulting `bigint` is in the range [0, 2^256 - 1]. It may be ≥ p;
 * callers are responsible for reducing it if needed (e.g., via
 * {@link reduce256Curve25519}).
 *
 * @param bytes - The source byte array (must be at least `offset + 32` bytes long).
 * @param offset - Byte index at which to start reading the 32-byte window.
 * @returns The big-endian decoded `bigint` for bytes `[offset, offset+32)`.
 *
 * @internal
 */
function bytesToBigintBECurve25519(bytes: Uint8Array, offset: number): bigint {
  const slice = bytes.slice(offset, offset + U256_BYTE_LENGTH);
  const u256BeBytes = createU256BeBytes(slice);
  return decodeU256BeBytesToU256(u256BeBytes);
}

/**
 * Factory that creates a sampler converting 512-bit big-endian byte arrays to
 * uniformly distributed Curve25519 field elements.
 *
 * @remarks
 * ## Purpose
 *
 * Hash-to-field algorithms produce 512-bit outputs to avoid statistical bias
 * when mapping into the 255-bit field. This factory encapsulates the standard
 * two-half combination technique (see below), returning a closure that can be
 * used repeatedly.
 *
 * ## Algorithm
 *
 * Given a 64-byte big-endian input array:
 *
 * 1. **Split** into two 256-bit halves:
 *    - `high = input[0..31]`  (most significant)
 *    - `low  = input[32..63]` (least significant)
 *
 * 2. **Reduce** each half into [0, p) via constant-time trial subtraction
 *    (`reduce256Curve25519`).
 *
 * 3. **Combine** using the precomputed constant R = 2^256 mod p = 38:
 *    ```
 *    result = (highReduced × R + lowReduced)  mod p
 *    ```
 *
 * ## Customization via `deps`
 *
 * The `modAdd` and `modMul` slots in `deps` allow replacing the default
 * constant-time implementations with alternatives. Common use cases:
 * - Inject test stubs to exercise the combination logic in isolation.
 * - Use a faster non-constant-time implementation for offline tooling.
 *
 * ## Uniformity
 *
 * The bias of the result is bounded by p / 2^512 < 2^-257, which is
 * negligible for all practical cryptographic purposes.
 *
 * @param deps - Optional overrides for modular arithmetic. If omitted, uses
 *   the default constant-time SDK implementations.
 * @returns A closure `(input: U512BeBytes) => Curve25519FieldElement`.
 *
 * @example
 * ```typescript
 * import { getCurve25519FieldElementSampler } from "@umbra-privacy/sdk";
 *
 * // Default: uses SDK constant-time arithmetic
 * const sampler = getCurve25519FieldElementSampler();
 *
 * const input = crypto.getRandomValues(new Uint8Array(64)) as U512BeBytes;
 * const element = sampler(input);
 * // element is a valid Curve25519FieldElement in [0, p-1]
 *
 * // With custom multiplication for testing
 * const testSampler = getCurve25519FieldElementSampler({
 *   modMul: (a, b) => (a * b) % ((1n << 255n) - 19n),
 * });
 * ```
 *
 * @see {@link curve25519FieldElementSampler} — pre-built default instance
 * @see {@link U512BasedCurve25519FieldElementSamplerDeps} — the dependency injection bag
 * @see {@link U512BasedCurve25519FieldElementSamplerFunction} — the returned function's type
 *
 * @public
 */
export function getCurve25519FieldElementSampler(
  deps?: U512BasedCurve25519FieldElementSamplerDeps,
): U512BasedCurve25519FieldElementSamplerFunction {
  // Use provided functions or fall back to defaults
  const { modAdd: moduleAdd = curve25519ModuloAdd, modMul: moduleMul = curve25519ModuloMul } =
    deps ?? {};

  return (input: U512BeBytes): Curve25519FieldElement => {
    // Extract high and low 256-bit halves (big-endian)
    // bytes 0-31 = high (most significant)
    // bytes 32-63 = low (least significant)
    const high = bytesToBigintBECurve25519(input, 0); // bytes 0-31
    const low = bytesToBigintBECurve25519(input, 32); // bytes 32-63

    // Reduce both halves to [0, p)
    // This is necessary because 256-bit values can be >= p
    const lowReduced = reduce256Curve25519(low);
    const highReduced = reduce256Curve25519(high);

    // Compute: result = (high × R + low) mod p
    // where R = 2^256 mod p = 38 for Curve25519
    const highTimesR = moduleMul(highReduced, R_MOD_P_CURVE25519);
    const result = moduleAdd(highTimesR, lowReduced);

    return result as Curve25519FieldElement;
  };
}

/**
 * Pre-instantiated U512-to-field-element sampler using the default
 * constant-time Curve25519 field arithmetic.
 *
 * @remarks
 * This is a convenience export for callers that do not need to inject custom
 * arithmetic. It is equivalent to calling:
 * ```typescript
 * getCurve25519FieldElementSampler()
 * ```
 * but avoids the factory call overhead for the common case.
 *
 * ## Typical Usage Pattern
 *
 * Hash-to-field: pass the 512-bit output of a wide hash (SHA-512, BLAKE2b-512,
 * HKDF output, etc.) directly to this sampler to obtain a uniformly distributed
 * field element:
 * ```
 * fieldElement = sampler(sha512(domainSeparator || message))
 * ```
 *
 * This pattern is used internally in the Umbra SDK wherever a scalar must be
 * derived deterministically from a secret without bias.
 *
 * @param input - A 64-byte big-endian byte array (`U512BeBytes`).
 * @returns A `Curve25519FieldElement` in the canonical range [0, p-1].
 *
 * @example
 * ```typescript
 * import { curve25519FieldElementSampler } from "@umbra-privacy/sdk";
 *
 * // All-zero input → deterministic result (== 0n)
 * const zeroInput = new Uint8Array(64) as U512BeBytes;
 * const element = curve25519FieldElementSampler(zeroInput);
 * console.log(element); // 0n
 *
 * // Random 64-byte input from a CSPRNG
 * const randomInput = crypto.getRandomValues(new Uint8Array(64)) as U512BeBytes;
 * const randomElement = curve25519FieldElementSampler(randomInput);
 * // randomElement is uniformly distributed in [0, p-1]
 * ```
 *
 * @see {@link getCurve25519FieldElementSampler} — factory for custom arithmetic
 * @see {@link U512BasedCurve25519FieldElementSamplerFunction} — the function type
 *
 * @public
 */
export const curve25519FieldElementSampler: U512BasedCurve25519FieldElementSamplerFunction =
  getCurve25519FieldElementSampler();
