/**
 * BN254 Field Element Types
 *
 * This module defines the foundational type primitives for working with elements
 * of the BN254 (alt_bn128) prime field. BN254 is a pairing-friendly elliptic curve
 * widely used in zero-knowledge proof systems, including Groth16, PLONK, and the
 * Circom/SnarkJS toolchain. Ethereum natively supports BN254 via the EIP-196 and
 * EIP-197 precompiles.
 *
 * @remarks
 * The BN254 scalar field F_r is the prime field whose order is the `r`-order of
 * points on the curve — i.e., the number of points on the curve's cyclic group.
 * All arithmetic in ZK circuits (Circom constraints, Groth16 witness values, etc.)
 * is performed modulo this prime. The prime has approximately 254 significant bits,
 * providing roughly 127 bits of symmetric security.
 *
 * The branded type system used here (`SubSubBrandedType`) enforces at compile time
 * that raw `bigint` values have been validated and reduced into the field. This
 * prevents accidentally passing an unreduced value (e.g., a product before modular
 * reduction) where a field element is expected.
 *
 * @see {@link https://eips.ethereum.org/EIPS/eip-196} EIP-196: Precompile for elliptic curve addition and scalar multiplication on alt_bn128
 * @see {@link https://eips.ethereum.org/EIPS/eip-197} EIP-197: Precompile for optimal ate pairing check on alt_bn128
 * @see {@link https://eprint.iacr.org/2010/354} Original BN curve construction paper
 *
 * @packageDocumentation
 * @module math/bn254/types
 */

import type { SubSubBrandedType } from "../../common/branded";
import type { U256 } from "../../common/types";
import { CryptographyAssertionError } from "../../common/errors";

/**
 * The prime field modulus for the BN254 (alt_bn128) scalar field F_r.
 *
 * @remarks
 * This is the order `r` of the prime-order subgroup of points on the BN254
 * elliptic curve, also known as the BN254 scalar field prime. Every arithmetic
 * operation in Groth16 proofs, Circom circuits, and Poseidon hashes operates
 * modulo this value.
 *
 * Hexadecimal: `0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001`
 *
 * The decimal representation is:
 * `21888242871839275222246405745257275088548364400416034343698204186575808495617`
 *
 * Properties:
 * - Bit length: 254 bits
 * - Security level: approximately 127 bits
 * - Used by Ethereum precompiles EIP-196, EIP-197
 * - The lowest limb (64-bit) is `0x43e1f593f0000001`
 *
 * @example
 * ```typescript
 * import { BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Reduce an arbitrary bigint into the field
 * const arbitrary = 99999999999999999999999999999999999999999999999999999999999999999999999999999n;
 * const reduced = arbitrary % BN254_FIELD_PRIME;
 * // reduced is now in [0, BN254_FIELD_PRIME - 1]
 * ```
 *
 * @public
 */
export const BN254_FIELD_PRIME =
  21_888_242_871_839_275_222_246_405_745_257_275_088_548_364_400_416_034_343_698_204_186_575_808_495_617n;

/**
 * A type-safe branded representation of a BN254 (alt_bn128) scalar field element.
 *
 * BN254 is a pairing-friendly elliptic curve that is the foundation of Ethereum's
 * SNARK precompiles and the Circom/Groth16 ecosystem. The scalar field F_r consists
 * of all integers in the range `[0, BN254_FIELD_PRIME - 1]`.
 *
 * @remarks
 * ## Why a Branded Type?
 *
 * A `bigint` can represent any integer, including values outside the field range.
 * Using a branded type ensures that:
 * 1. Only values that have been explicitly validated (via `assertBn254FieldElement`)
 *    can be assigned to this type.
 * 2. The TypeScript compiler will reject attempts to pass an arbitrary `bigint` where
 *    a `Bn254FieldElement` is expected, catching a whole class of cryptographic bugs.
 * 3. Intermediate values produced by field operations (e.g., `a * b` before reduction)
 *    cannot be accidentally used as field elements.
 *
 * ## BN254 Curve Properties
 *
 * - Curve equation: `y^2 = x^3 + 3` over F_p (where p is the base field prime)
 * - Scalar field order: `r = 21888242871839275222246405745257275088548364400416034343698204186575808495617`
 * - Embedding degree: 12 (makes it pairing-friendly)
 * - Security level: ~100 bits (conservative estimate accounting for NFS attacks on pairings)
 * - Supported operations: Groth16 verification, Poseidon hashing, EdDSA (Baby Jubjub)
 *
 * ## Usage
 *
 * Values of this type are inputs and outputs of all field arithmetic functions in
 * this module (`bn254Add`, `bn254Mul`, etc.) and the Poseidon hash functions.
 *
 * @see {@link assertBn254FieldElement} The assertion function that produces values of this type
 * @see {@link BN254_FIELD_PRIME} The modulus that defines the field
 * @see {@link https://eips.ethereum.org/EIPS/eip-196} EIP-196
 *
 * @example
 * ```typescript
 * import { type Bn254FieldElement, assertBn254FieldElement, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Validate and brand a known constant
 * const one = 1n;
 * assertBn254FieldElement(one, "one");
 * // one is now typed as Bn254FieldElement
 *
 * // The type prevents mixing with plain bigint in function signatures
 * function requiresFieldElement(x: Bn254FieldElement): void { /* ... *\/ }
 * requiresFieldElement(42n); // TypeScript compile error
 * requiresFieldElement(one); // OK
 * ```
 *
 * @public
 */
export type Bn254FieldElement = SubSubBrandedType<U256, "Bn254FieldElement">;

/**
 * Asserts that a `bigint` value is a valid element of the BN254 scalar field F_r,
 * narrowing its TypeScript type to `Bn254FieldElement` upon success.
 *
 * @remarks
 * A value is considered a valid BN254 field element if and only if:
 * 1. It is of type `bigint` (not `number`, `string`, etc.)
 * 2. It is non-negative: `value >= 0n`
 * 3. It is strictly less than the field prime: `value < BN254_FIELD_PRIME`
 *
 * This function uses the TypeScript assertion signature pattern (`asserts value is T`)
 * so that after a successful call, the narrowed type flows through to subsequent code
 * without any explicit cast.
 *
 * ## When to Use
 *
 * Call this function at the boundary between unvalidated external data and your
 * internal cryptographic logic. For example:
 * - When deserializing a field element from bytes
 * - When accepting user input that will be used as a circuit witness
 * - After computing a value from external sources before passing it to field operations
 *
 * Internally, all field arithmetic functions in this module automatically produce
 * validated `Bn254FieldElement` values, so you do not need to re-validate their outputs.
 *
 * @param value - The `bigint` to validate. Must satisfy `0 <= value < BN254_FIELD_PRIME`.
 * @param name - A descriptive name for the value, used in error messages to aid debugging.
 *   Defaults to `"value"` if not provided.
 * @defaultValue `name` defaults to `"value"`
 *
 * @throws {CryptographyAssertionError} If `value` is not a `bigint`.
 * @throws {CryptographyAssertionError} If `value` is negative (i.e., `value < 0n`).
 * @throws {CryptographyAssertionError} If `value` is greater than or equal to the field prime.
 *
 * @example
 * ```typescript
 * import { assertBn254FieldElement, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Valid usage
 * const raw = 12345n;
 * assertBn254FieldElement(raw, "raw");
 * // After this line, `raw` is typed as Bn254FieldElement
 *
 * // The maximum valid field element is BN254_FIELD_PRIME - 1n
 * const maxElement = BN254_FIELD_PRIME - 1n;
 * assertBn254FieldElement(maxElement, "maxElement"); // OK
 *
 * // These all throw CryptographyAssertionError:
 * assertBn254FieldElement(-1n, "negativeValue");   // Throws: negativeValue is negative
 * assertBn254FieldElement(BN254_FIELD_PRIME, "atPrime"); // Throws: atPrime exceeds field prime
 * assertBn254FieldElement(42 as unknown as bigint, "notBigint"); // Throws: expected bigint
 * ```
 *
 * @see {@link Bn254FieldElement} The branded type this function produces
 * @see {@link BN254_FIELD_PRIME} The field modulus used for range checking
 * @see {@link CryptographyAssertionError} The error type thrown on validation failure
 *
 * @public
 */
export function assertBn254FieldElement(
  value: bigint,
  name = "value",
): asserts value is Bn254FieldElement {
  const variableName = name;
  if (typeof value !== "bigint") {
    throw new CryptographyAssertionError(`${variableName}: Expected bigint, got ${typeof value}`, {
      value,
      expectedType: "Bn254FieldElement",
    });
  }
  if (value < 0n) {
    throw new CryptographyAssertionError(`${variableName}: Value ${String(value)} is negative`, {
      value,
      expectedType: "Bn254FieldElement",
      constraint: "value >= 0",
    });
  }
  if (value >= BN254_FIELD_PRIME) {
    throw new CryptographyAssertionError(`${variableName}: Value exceeds BN254 field prime`, {
      value,
      expectedType: "Bn254FieldElement",
      constraint: `value < ${String(BN254_FIELD_PRIME)}`,
    });
  }
}
