/**
 * BN254 Field Element Sampler Implementation
 *
 * This module provides a constant-time implementation for sampling BN254 scalar
 * field elements from 512-bit big-endian byte arrays. The primary use case is
 * deriving field elements from hash outputs (e.g., SHA-512, Keccak-512) or from
 * concatenated CSPRNG outputs, as required by Fiat-Shamir transformations and
 * key derivation in ZK proof systems.
 *
 * @remarks
 * ## Why 512 Bits?
 *
 * The BN254 scalar field prime `p` is approximately `2^254`. If a 256-bit
 * random value were mapped directly into the field via `value mod p`, there would
 * be a statistical bias: the values in `[0, 2^256 mod p - 1]` would appear with
 * probability `2/(floor(2^256 / p) + 1)`, while higher values appear with
 * probability `1/(floor(2^256 / p) + 1)`. This bias is approximately `2^(-127)`,
 * which is borderline for cryptographic applications.
 *
 * Using a 512-bit input reduces the maximum bias to approximately `2^(-254)`,
 * which is cryptographically negligible for any practical security level.
 *
 * ## Algorithm
 *
 * Given a 512-bit big-endian input `h`, the module:
 * 1. Splits `h` into two 256-bit halves (`high = h[0..31]`, `low = h[32..63]`)
 * 2. Reduces both halves to `[0, p)` using constant-time trial subtraction (`reduce256`)
 * 3. Computes `result = (high * R + low) mod p` where `R = 2^256 mod p`
 *    (the Montgomery constant for converting from 512-bit to field element)
 *
 * This is equivalent to interpreting the 512-bit value as an integer and reducing
 * it modulo `p` in a constant-time manner.
 *
 * ## Constant-Time Guarantees
 *
 * All internal operations are constant-operation-count:
 * - `ctSelect`: bitwise masking instead of branching
 * - `bigintToLimbs` / `limbsToBigint`: fixed 4-limb operations
 * - `conditionalSubtractP`: always subtracts and always selects (via mask)
 * - `reduce256`: exactly 5 conditional subtractions, no early exit
 *
 * True hardware-level constant time cannot be guaranteed in JavaScript due to JIT
 * compilation and BigInt internals, but the implementation avoids all data-dependent
 * control flow.
 *
 * @see {@link ./interfaces.U512BasedBn254FieldElementSamplerFunction} Interface type
 * @see {@link ./interfaces.U512BasedBn254FieldElementSamplerDeps} Dependency injection type
 * @see {@link ./field-arithmetic} The constant-time modular arithmetic layer
 *
 * @packageDocumentation
 * @module math/bn254/field-element-sampler
 */

import type {
  U512BasedBn254FieldElementSamplerFunction as U512BasedBn254FieldElementSamplerFunction,
  U512BasedBn254FieldElementSamplerDeps,
} from "./interfaces";
import { type U512BeBytes, U256_BYTE_LENGTH } from "../../common/types";
import { createU256BeBytes } from "../../common/converters/branded";
import { decodeU256BeBytesToU256 } from "../../common/converters/mathematics";
import {
  bn254ModuloAdd as bn254ModuleAdd,
  bn254ModuloMul as bn254ModuleMul,
} from "./field-arithmetic";

/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * Number of bits per 64-bit limb, as a `bigint` for use in shift operations.
 *
 * @remarks
 * Used throughout the limb arithmetic to shift values by 64-bit positions.
 * Storing as a `bigint` avoids repeated conversions in hot paths.
 *
 * @internal
 */
const N64 = 64n;

/**
 * Bit mask for extracting the lower 64 bits of a `bigint`.
 *
 * @remarks
 * Equal to `2^64 - 1 = 0xFFFFFFFFFFFFFFFF`. Applied via bitwise AND to
 * isolate the 64-bit limb after addition or shift operations that may
 * produce values wider than 64 bits.
 *
 * @internal
 */
const MASK64 = 0xff_ff_ff_ff_ff_ff_ff_ffn;

/**
 * The BN254 scalar field prime `p` decomposed into four 64-bit little-endian limbs.
 *
 * @remarks
 * The prime is:
 * `p = 21888242871839275222246405745257275088548364400416034343698204186575808495617`
 * In hexadecimal: `0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001`
 *
 * Limb decomposition (little-endian, each limb is 64 bits):
 * - `P_LIMBS[0]` = `0x43e1f593f0000001` (bits 0–63)
 * - `P_LIMBS[1]` = `0x2833e84879b97091` (bits 64–127)
 * - `P_LIMBS[2]` = `0xb85045b68181585d` (bits 128–191)
 * - `P_LIMBS[3]` = `0x30644e72e131a029` (bits 192–255)
 *
 * This representation mirrors that used in `field-arithmetic.ts` and is required
 * for the constant-time `conditionalSubtractP` function below.
 *
 * @internal
 */
const P_LIMBS: readonly [bigint, bigint, bigint, bigint] = [
  0x43_e1_f5_93_f0_00_00_01n, // limb 0 (bits 0-63)
  0x28_33_e8_48_79_b9_70_91n, // limb 1 (bits 64-127)
  0xb8_50_45_b6_81_81_58_5dn, // limb 2 (bits 128-191)
  0x30_64_4e_72_e1_31_a0_29n, // limb 3 (bits 192-255)
];

/**
 * The Montgomery constant `R = 2^256 mod p`.
 *
 * @remarks
 * This value is used to map a 512-bit integer into the field by computing:
 * ```
 * result = (high * R + low) mod p
 * ```
 * where `high` and `low` are the two 256-bit halves of the 512-bit input.
 *
 * Derivation:
 * `R = 2^256 mod p`
 * `  = 6350874878119819312338956282401532410528162663560392320966563075034087161851`
 *
 * This value was computed as:
 * `(2n ** 256n) % 21888242871839275222246405745257275088548364400416034343698204186575808495617n`
 *
 * @internal
 */
const R_MOD_P =
  6_350_874_878_119_819_312_338_956_282_401_532_410_528_162_663_560_392_320_966_563_075_034_087_161_851n;

/* =============================================================================
 * INTERNAL HELPER FUNCTIONS
 * ============================================================================= */

/**
 * Performs a constant-time conditional select between two `bigint` values.
 *
 * Returns `x` if `bit === 1n`, or `y` if `bit === 0n`, using bitwise masking
 * instead of a conditional branch.
 *
 * @remarks
 * ## How It Works
 *
 * In two's complement arithmetic, `-1n` has all bits set (`0xFFFF...FFFF`).
 * The mask is computed as `-bit`:
 * - If `bit === 1n`: `mask = -1n` (all bits set), so `(x & mask) | (y & ~mask) = x | 0 = x`
 * - If `bit === 0n`: `mask = 0n` (no bits set), so `(x & mask) | (y & ~mask) = 0 | y = y`
 *
 * Note: JavaScript's `bigint` supports arbitrary-precision two's complement, so
 * `-1n` in `bigint` arithmetic behaves as an infinite sequence of set bits, making
 * this idiom well-defined and safe.
 *
 * @param bit - Selection bit: must be exactly `0n` or `1n`.
 * @param x - Value returned when `bit === 1n`.
 * @param y - Value returned when `bit === 0n`.
 * @returns `x` if `bit === 1n`; `y` otherwise.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const chosen = ctSelect(1n, 42n, 99n); // 42n
 * const other  = ctSelect(0n, 42n, 99n); // 99n
 * ```
 *
 * @internal
 */
function ctSelect(bit: bigint, x: bigint, y: bigint): bigint {
  const mask = -bit;
  return (x & mask) | (y & ~mask);
}

/**
 * Converts a `bigint` value to a 4-element little-endian 64-bit limb array.
 *
 * @remarks
 * Each limb is isolated via a right shift and a 64-bit mask:
 * ```
 * limb[k] = (value >> (64 * k)) & MASK64
 * ```
 * The input `value` should be in the range `[0, 2^256 - 1]` for a meaningful
 * 4-limb representation; higher bits are silently truncated.
 *
 * @param value - The `bigint` to decompose into 64-bit limbs.
 * @returns A 4-tuple `[limb0, limb1, limb2, limb3]` in little-endian order.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const limbs = bigintToLimbs(1n); // [1n, 0n, 0n, 0n]
 * const shifted = bigintToLimbs(2n ** 64n); // [0n, 1n, 0n, 0n]
 * ```
 *
 * @internal
 */
function bigintToLimbs(value: bigint): readonly [bigint, bigint, bigint, bigint] {
  return [
    value & MASK64,
    (value >> N64) & MASK64,
    (value >> (N64 * 2n)) & MASK64,
    (value >> (N64 * 3n)) & MASK64,
  ];
}

/**
 * Reconstructs a `bigint` from a 4-element little-endian 64-bit limb array.
 *
 * @remarks
 * Applies the positional formula:
 * ```
 * value = limbs[0] + limbs[1] * 2^64 + limbs[2] * 2^128 + limbs[3] * 2^192
 * ```
 * This is the inverse of `bigintToLimbs`. The result is in the range
 * `[0, 2^256 - 1]` when all limbs are in `[0, 2^64 - 1]`.
 *
 * @param limbs - A 4-tuple `[limb0, limb1, limb2, limb3]` in little-endian order.
 * @returns The reconstructed `bigint` value.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const val = limbsToBigint([1n, 0n, 0n, 0n]); // 1n
 * const large = limbsToBigint([0n, 1n, 0n, 0n]); // 2^64
 * ```
 *
 * @internal
 */
function limbsToBigint(limbs: readonly [bigint, bigint, bigint, bigint]): bigint {
  return limbs[0] + (limbs[1] << N64) + (limbs[2] << (N64 * 2n)) + (limbs[3] << (N64 * 3n));
}

/**
 * Performs a single constant-time conditional subtraction of the field prime `p`.
 *
 * If `value >= p`, returns `value - p`. Otherwise returns `value` unchanged.
 * The selection between the two outcomes is performed using constant-time bitwise
 * masking to avoid data-dependent branching.
 *
 * @remarks
 * ## Algorithm
 *
 * 1. Perform a trial subtraction `d = value - p` across all 4 limbs with borrow
 *    propagation, tracking the final borrow bit (`borrow3`).
 * 2. `borrow3 === 1n` means `value < p` (subtraction underflowed); use original `value`.
 * 3. `borrow3 === 0n` means `value >= p` (no underflow); use the subtracted result `d`.
 * 4. Each limb of the output is selected via `ctSelect(useOriginal, original[k], d[k])`.
 *
 * This function is called up to 5 times by `reduce256` to fully reduce a 256-bit
 * value into the range `[0, p-1]`.
 *
 * @param limbs - The value to conditionally reduce, as a 4-tuple of 64-bit limbs.
 * @returns The conditionally subtracted result, still as a 4-tuple of 64-bit limbs.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const pLimbs = bigintToLimbs(BN254_FIELD_PRIME);
 * const reduced = conditionalSubtractP(pLimbs);
 * // reduced represents 0n (p - p = 0)
 *
 * const smallLimbs = bigintToLimbs(5n);
 * const unchanged = conditionalSubtractP(smallLimbs);
 * // unchanged still represents 5n (5 < p, no subtraction)
 * ```
 *
 * @internal
 */
function conditionalSubtractP(
  limbs: readonly [bigint, bigint, bigint, bigint],
): readonly [bigint, bigint, bigint, bigint] {
  const [l0, l1, l2, l3] = limbs;
  const [p0, p1, p2, p3] = P_LIMBS;

  // Trial subtraction: d = value - p
  const sub0 = l0 - p0;
  const d0 = sub0 & MASK64;
  const borrow0 = -(sub0 >> N64) & 1n;

  const sub1 = l1 - p1 - borrow0;
  const d1 = sub1 & MASK64;
  const borrow1 = -(sub1 >> N64) & 1n;

  const sub2 = l2 - p2 - borrow1;
  const d2 = sub2 & MASK64;
  const borrow2 = -(sub2 >> N64) & 1n;

  const sub3 = l3 - p3 - borrow2;
  const d3 = sub3 & MASK64;
  const borrow3 = -(sub3 >> N64) & 1n;

  // If borrow3 is 0, value >= p, so use d (the subtracted value)
  // If borrow3 is 1, value < p, so use original value
  const useOriginal = borrow3;

  return [
    ctSelect(useOriginal, l0, d0),
    ctSelect(useOriginal, l1, d1),
    ctSelect(useOriginal, l2, d2),
    ctSelect(useOriginal, l3, d3),
  ];
}

/**
 * Constant-time reduction of an arbitrary 256-bit integer to the canonical
 * representative in `[0, p)`.
 *
 * @remarks
 * ## Why 5 Subtractions?
 *
 * For a 256-bit value `v` in the range `[0, 2^256 - 1]`, the maximum number of
 * times `p` must be subtracted to reach the canonical range is:
 * ```
 * floor((2^256 - 1) / p) = floor(2^256 / p) ≈ 5.29
 * ```
 * Therefore, at most 6 subtractions are needed, but in practice 5 suffice for
 * any value strictly less than `2^256`. This function performs exactly 5
 * conditional subtractions unconditionally (constant-operation-count), ensuring
 * no data-dependent early termination.
 *
 * @param value - A 256-bit non-negative integer (`0 <= value < 2^256`).
 * @returns The unique representative of `value mod p` in `[0, p-1]`.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const bigValue = 2n ** 256n - 1n; // maximum 256-bit value
 * const reduced = reduce256(bigValue); // some value in [0, p-1]
 *
 * const alreadyReduced = 42n;
 * const same = reduce256(alreadyReduced); // 42n (unchanged)
 * ```
 *
 * @internal
 */
function reduce256(value: bigint): bigint {
  let limbs = bigintToLimbs(value);

  // Perform 5 conditional subtractions (constant-time)
  // This handles values up to ~5.29p (the maximum for 256-bit inputs)
  limbs = conditionalSubtractP(limbs);
  limbs = conditionalSubtractP(limbs);
  limbs = conditionalSubtractP(limbs);
  limbs = conditionalSubtractP(limbs);
  limbs = conditionalSubtractP(limbs);

  return limbsToBigint(limbs);
}

/**
 * Reads 32 bytes from `bytes` starting at `offset` and decodes them as a
 * big-endian unsigned 256-bit integer.
 *
 * @remarks
 * This is a thin adapter that extracts a 32-byte slice and delegates to the
 * project's canonical `decodeU256BeBytesToU256` converter. It exists to centralize
 * the slice-and-decode pattern used twice in the sampler (once for `high`, once
 * for `low`).
 *
 * @param bytes - The source byte array. Must have at least `offset + 32` bytes.
 * @param offset - The zero-based byte index at which to begin reading.
 * @returns The big-endian integer value of `bytes[offset .. offset + 32)`.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const input = new Uint8Array(64); // 64 zero bytes
 * const high = bytesToBigintBE(input, 0);  // 0n (bytes 0-31)
 * const low  = bytesToBigintBE(input, 32); // 0n (bytes 32-63)
 * ```
 *
 * @internal
 */
function bytesToBigintBE(bytes: Uint8Array, offset: number): bigint {
  const slice = bytes.slice(offset, offset + U256_BYTE_LENGTH);
  const u256BeBytes = createU256BeBytes(slice);
  return decodeU256BeBytesToU256(u256BeBytes);
}

/* =============================================================================
 * SAMPLER FACTORY
 * ============================================================================= */

/**
 * Creates a factory-configured U512-based BN254 field element sampler.
 *
 * Returns a closure that accepts a 64-byte big-endian byte array (`U512BeBytes`)
 * and produces a uniformly distributed element of the BN254 scalar field.
 *
 * @param deps - Optional dependency injection for custom modular arithmetic.
 *   When omitted, uses the production constant-time implementations from
 *   `field-arithmetic.ts` (`bn254ModuloAdd` and `bn254ModuloMul`).
 * @returns A `U512BasedBn254FieldElementSamplerFunction` closure bound to the
 *   provided (or default) arithmetic functions.
 *
 * @remarks
 * ## Algorithm
 *
 * The returned sampler function, when invoked with a 64-byte input `h`:
 *
 * 1. **Split**: reads `high = h[0..31]` and `low = h[32..63]` as big-endian integers.
 * 2. **Reduce**: calls `reduce256(high)` and `reduce256(low)` to bring both halves
 *    into `[0, p-1]` using constant-time trial subtraction.
 * 3. **Combine**: computes `result = modMul(highReduced, R) + modAdd(lowReduced)`
 *    — i.e., `(high * R + low) mod p` — where `R = 2^256 mod p`.
 *
 * This is mathematically equivalent to:
 * ```
 * result = (h interpreted as a 512-bit big-endian integer) mod p
 * ```
 *
 * ## Dependency Injection
 *
 * The `opts.modAdd` and `opts.modMul` overrides are applied to the final combine
 * step (step 3). The `reduce256` step always uses the internal constant-time
 * `conditionalSubtractP` regardless of injection. This design ensures that
 * tests can substitute the combine arithmetic while keeping the reduction step
 * deterministic.
 *
 * @example
 * ```typescript
 * import { getBn254FieldElementSampler } from "@umbra/sdk";
 *
 * // Default constant-time arithmetic
 * const sampler = getBn254FieldElementSampler();
 * const fieldElement = sampler(someU512Input);
 *
 * // Custom arithmetic for testing
 * const testSampler = getBn254FieldElementSampler({
 *   modAdd: (a, b) => (a + b) % BN254_FIELD_PRIME,
 *   modMul: (a, b) => (a * b) % BN254_FIELD_PRIME,
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Deriving a field element from two concatenated SHA-256 hashes
 * const hash1 = sha256(someData);        // 32 bytes
 * const hash2 = sha256(someOtherData);   // 32 bytes
 * const combined = new Uint8Array(64);
 * combined.set(hash1, 0);
 * combined.set(hash2, 32);
 * assertU512BeBytes(combined);
 *
 * const sampler = getBn254FieldElementSampler();
 * const fieldElement = sampler(combined);
 * // fieldElement is a well-distributed BN254 field element derived from the hashes
 * ```
 *
 * @see {@link bn254FieldElementSampler} Pre-instantiated default sampler
 * @see {@link U512BasedBn254FieldElementSamplerDeps} Dependency injection interface
 * @see {@link U512BasedBn254FieldElementSamplerFunction} The returned function type
 *
 * @public
 */
export function getBn254FieldElementSampler(
  deps?: U512BasedBn254FieldElementSamplerDeps,
): U512BasedBn254FieldElementSamplerFunction {
  // Use provided functions or fall back to defaults
  const { modAdd: moduleAdd = bn254ModuleAdd, modMul: moduleMul = bn254ModuleMul } = deps ?? {};

  return (input: U512BeBytes): bigint => {
    // Extract high and low 256-bit halves (big-endian)
    // bytes 0-31 = high (most significant)
    // bytes 32-63 = low (least significant)
    const high = bytesToBigintBE(input, 0); // bytes 0-31
    const low = bytesToBigintBE(input, 32); // bytes 32-63

    // Reduce both halves to [0, p)
    // This is necessary because 256-bit values can be >= p
    const lowReduced = reduce256(low);
    const highReduced = reduce256(high);

    // Compute: result = (high × R + low) mod p
    // where R = 2^256 mod p
    const highTimesR = moduleMul(highReduced, R_MOD_P);
    const result = moduleAdd(highTimesR, lowReduced);

    return result;
  };
}

/**
 * The pre-instantiated default U512-based BN254 field element sampler.
 *
 * This is a convenience export of `getBn254FieldElementSampler()` with
 * no arguments — using the default constant-time `bn254ModuloAdd` and
 * `bn254ModuloMul` implementations from `field-arithmetic.ts`.
 *
 * @remarks
 * Use this export directly when you do not need to inject custom arithmetic.
 * It avoids the overhead of calling the factory function on every use.
 *
 * The sampler is stateless (it is a pure function of its input), so sharing this
 * instance across multiple call sites is safe.
 *
 * @example
 * ```typescript
 * import { bn254FieldElementSampler } from "@umbra/sdk";
 *
 * // Produce a field element from a 64-byte CSPRNG output
 * const randomBytes = crypto.getRandomValues(new Uint8Array(64));
 * assertU512BeBytes(randomBytes);
 * const fieldElement = bn254FieldElementSampler(randomBytes);
 * // fieldElement is a uniformly distributed BN254 scalar field element
 * ```
 *
 * @see {@link getBn254FieldElementSampler} The factory for custom configurations
 * @see {@link U512BasedBn254FieldElementSamplerFunction} The function type
 *
 * @public
 */
export const bn254FieldElementSampler: U512BasedBn254FieldElementSamplerFunction =
  getBn254FieldElementSampler();
