/**
 * Curve25519 Base Field Types
 *
 * This module defines the branded type and validation primitives for elements
 * of the Curve25519 base field, whose prime modulus is p = 2^255 - 19.
 *
 * ## What is Curve25519?
 *
 * Curve25519 is a Montgomery-form elliptic curve designed by Daniel J. Bernstein
 * for high-performance, side-channel-resistant Diffie-Hellman key exchange. It is
 * specified in RFC 7748 and underlies two widely deployed cryptographic primitives:
 *
 * - **X25519** — Diffie-Hellman key agreement. Used in Umbra for encrypted token
 *   account key registration (users register an X25519 public key so MXE-encrypted
 *   balances can be shared with them).
 * - **Ed25519** — Digital signatures (uses the twisted-Edwards form of the same
 *   underlying field).
 *
 * ## The Base Field GF(p)
 *
 * All Curve25519 point coordinates are elements of the prime field GF(p) where:
 * ```
 * p = 2^255 - 19
 *   = 57896044618658097711785492504343953926634992332820282019728792003956564819949
 * ```
 *
 * The near-power-of-two structure of p makes modular reduction especially
 * efficient: because p ≡ -19 (mod 2^255), any reduction can be expressed as a
 * small multiply-and-add rather than a full division.
 *
 * ## Rescue-XLIX Cipher
 *
 * Within the Umbra SDK, field arithmetic over GF(p) is used primarily by the
 * **Rescue-XLIX block cipher** (see `crypto/rescue-cipher/`). Rescue-XLIX operates
 * over this same field and is the symmetric cipher used inside Arcium MPC
 * computations to produce and verify ciphertexts for encrypted Umbra token accounts.
 *
 * ## Contrast with BN254
 *
 * The SDK also provides `math/bn254/` for the BN254 scalar field
 * (p ≈ 2^254, ~100-bit security, pairing-friendly). That field is used for
 * Groth16 ZK proofs and Poseidon hashes. The two fields are **not interchangeable**:
 * elements of one field are not valid elements of the other.
 *
 * ## Branded Types
 *
 * `Curve25519FieldElement` is a branded `bigint` subtype. The branding enforces
 * at compile time that only validated, in-range values are passed to field
 * arithmetic functions, preventing silent truncation bugs.
 *
 * @module math/curve25519/types
 * @packageDocumentation
 */

import type { SubSubBrandedType } from "../../common/branded";
import type { U256 } from "../../common/types";
import { CryptographyAssertionError } from "../../common/errors";

/**
 * The prime field modulus for the Curve25519 base field.
 *
 * @remarks
 * Defined as p = 2^255 - 19. In decimal:
 * ```
 * 57896044618658097711785492504343953926634992332820282019728792003956564819949
 * ```
 *
 * The near-power-of-two form is critical for efficient modular reduction: since
 * 2^255 ≡ 19 (mod p), a 256-bit product can be reduced using a single
 * multiplication by 19 and an addition, rather than a general division.
 *
 * This constant is shared by all field arithmetic operations in this module and
 * by the Rescue-XLIX cipher implementation in `crypto/rescue-cipher/`.
 *
 * @example
 * ```typescript
 * import { CURVE25519_FIELD_PRIME } from "@umbra-privacy/sdk";
 *
 * // Verify the prime is 2^255 - 19
 * const expected = (1n << 255n) - 19n;
 * console.log(CURVE25519_FIELD_PRIME === expected); // true
 *
 * // Manual modular reduction
 * const x = 2n ** 300n;
 * const reduced = x % CURVE25519_FIELD_PRIME;
 * ```
 *
 * @public
 */
export const CURVE25519_FIELD_PRIME = (1n << 255n) - 19n;

/**
 * Branded type representing a validated element of the Curve25519 base field
 * GF(2^255 - 19).
 *
 * @remarks
 * A `Curve25519FieldElement` is a `bigint` that has been verified to lie in the
 * canonical range [0, p-1] where p = 2^255 - 19. The branding is a
 * compile-time phantom that prevents unvalidated bigints from being passed
 * to functions that expect field elements.
 *
 * The type sits at the third level of the branded-type hierarchy:
 * ```
 * bigint
 *   └── U256            (branded bigint: 0 ≤ value < 2^256)
 *         └── Curve25519FieldElement  (branded U256: 0 ≤ value < p)
 * ```
 *
 * Unlike BN254FieldElement (used for Groth16 proofs / Poseidon hashes),
 * Curve25519FieldElement operates over a **different prime** and must not be
 * mixed with BN254 arithmetic. Field elements from the two curves are
 * structurally identical at runtime (both are `bigint`) but semantically
 * incompatible; the branded type hierarchy enforces this distinction
 * statically.
 *
 * ## Security Properties
 *
 * - Provides approximately 128 bits of security for discrete-logarithm problems.
 * - Curve25519 is designed to resist timing attacks: the prime's structure
 *   permits implementations with uniform execution paths.
 * - Used in X25519 (ECDH) for Umbra encrypted token account key registration
 *   and in Rescue-XLIX for MPC-layer symmetric encryption.
 *
 * @example
 * ```typescript
 * import {
 *   assertCurve25519FieldElement,
 *   type Curve25519FieldElement,
 * } from "@umbra-privacy/sdk";
 *
 * // Obtain a branded field element after validation
 * const raw = 12345n;
 * assertCurve25519FieldElement(raw, "raw");
 * const element: Curve25519FieldElement = raw;
 *
 * // Type error: plain bigint is not assignable to Curve25519FieldElement
 * // const bad: Curve25519FieldElement = 12345n; // compile error
 * ```
 *
 * @see {@link assertCurve25519FieldElement} — runtime validator that narrows `bigint` to this type
 * @see {@link CURVE25519_FIELD_PRIME} — the field prime p = 2^255 - 19
 * @see https://cr.yp.to/ecdh/curve25519-20060209.pdf — original Curve25519 specification
 * @see https://www.rfc-editor.org/rfc/rfc7748 — X25519 / X448 RFC
 *
 * @public
 */
export type Curve25519FieldElement = SubSubBrandedType<U256, "Curve25519FieldElement">;

/**
 * Asserts that a `bigint` value is a valid Curve25519 base field element,
 * narrowing its TypeScript type to `Curve25519FieldElement` on success.
 *
 * @remarks
 * Validation checks, in order:
 * 1. The value must be a `bigint` (not `number`, `string`, etc.).
 * 2. The value must be non-negative: value ≥ 0.
 * 3. The value must be strictly less than the field prime: value < 2^255 - 19.
 *
 * This function is an **assertion function** (TypeScript `asserts` predicate).
 * After a successful call, the TypeScript compiler narrows the type of the
 * variable at the call site to `Curve25519FieldElement`, enabling it to be
 * used in APIs that require a validated field element without an explicit cast.
 *
 * Callers should use this function at trust boundaries — e.g., when accepting
 * field elements from user input, deserialization, or across module boundaries —
 * and rely on the typed field arithmetic functions afterwards.
 *
 * @param value - The `bigint` to validate. Must satisfy 0 ≤ value < 2^255 - 19.
 * @param name - Human-readable variable name for error messages. Defaults to
 *   `"value"`. Provide a descriptive name to make assertion errors actionable.
 *
 * @throws {CryptographyAssertionError} If `value` is not a `bigint`.
 * @throws {CryptographyAssertionError} If `value` is negative (value < 0).
 * @throws {CryptographyAssertionError} If `value` is out of range (value ≥ p).
 *
 * @example
 * ```typescript
 * import {
 *   assertCurve25519FieldElement,
 *   CURVE25519_FIELD_PRIME,
 * } from "@umbra-privacy/sdk";
 *
 * // Valid: in-range bigint — type is narrowed to Curve25519FieldElement
 * const a = 12345n;
 * assertCurve25519FieldElement(a, "a");
 * // a is now Curve25519FieldElement
 *
 * // Invalid: negative value
 * assertCurve25519FieldElement(-1n, "myValue");
 * // throws CryptographyAssertionError: "myValue: Value -1 is negative"
 *
 * // Invalid: equals the field prime (must be strictly less)
 * assertCurve25519FieldElement(CURVE25519_FIELD_PRIME, "myValue");
 * // throws CryptographyAssertionError: "myValue: Value exceeds Curve25519 field prime"
 *
 * // Invalid: not a bigint
 * assertCurve25519FieldElement(42 as unknown as bigint, "myValue");
 * // throws CryptographyAssertionError: "myValue: Expected bigint, got number"
 * ```
 *
 * @see {@link Curve25519FieldElement} — the branded type this function produces
 * @see {@link CURVE25519_FIELD_PRIME} — the upper bound (exclusive) for valid elements
 *
 * @public
 */
export function assertCurve25519FieldElement(
  value: bigint,
  name = "value",
): asserts value is Curve25519FieldElement {
  const variableName = name;
  if (typeof value !== "bigint") {
    throw new CryptographyAssertionError(`${variableName}: Expected bigint, got ${typeof value}`, {
      value,
      expectedType: "Curve25519FieldElement",
    });
  }
  if (value < 0n) {
    throw new CryptographyAssertionError(`${variableName}: Value ${String(value)} is negative`, {
      value,
      expectedType: "Curve25519FieldElement",
      constraint: "value >= 0",
    });
  }
  if (value >= CURVE25519_FIELD_PRIME) {
    throw new CryptographyAssertionError(`${variableName}: Value exceeds Curve25519 field prime`, {
      value,
      expectedType: "Curve25519FieldElement",
      constraint: "value < 2^255 - 19",
    });
  }
}
