/**
 * BN254 Field Arithmetic — Constant-Time Montgomery Implementation
 *
 * This module provides the core constant-time modular arithmetic operations for
 * the BN254 (alt_bn128) scalar prime field F_r. It is the cryptographic foundation
 * of the BN254 math layer and implements all five field operations:
 *
 * - Addition: `(a + b) mod p`
 * - Subtraction: `(a - b) mod p`
 * - Multiplication: `(a * b) mod p` (via Montgomery multiplication)
 * - Negation: `-a mod p`
 * - Multiplicative inverse: `a^(-1) mod p` (via Fermat + Montgomery exponentiation)
 *
 * Additionally, it exports getter functions that return stable cached instances of
 * each operation, and a utility for computing the modular inverse of a Base85 limb sum.
 *
 * @remarks
 * ## BN254 Scalar Field
 *
 * The BN254 elliptic curve (also called alt_bn128 in the Ethereum context) has a
 * cyclic group of prime order:
 * ```
 * p = 21888242871839275222246405745257275088548364400416034343698204186575808495617
 *   = 0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001
 * ```
 * This prime has approximately 254 significant bits. Every arithmetic operation in
 * Circom circuits, Groth16 proofs, and Poseidon hashes works modulo `p`.
 *
 * ## Constant-Time Design
 *
 * These implementations target *constant-operation-count* behavior, which is the
 * achievable standard in JavaScript:
 * - No data-dependent branching on secret values
 * - All 4 limbs are always processed uniformly
 * - Conditional selection uses bitwise masking (`ctSelect`)
 * - Montgomery multiplication processes all iterations unconditionally
 *
 * True hardware-level constant time (immune to microarchitectural attacks such as
 * cache-timing, branch prediction, and power analysis) is not achievable in JavaScript
 * due to the JIT compiler and BigInt internals. However, this implementation avoids
 * the most obvious timing leaks.
 *
 * ## 4-Limb (64-bit) Representation
 *
 * Values are stored as `[limb0, limb1, limb2, limb3]` in little-endian order:
 * - `limb0`: bits 0–63 (least significant)
 * - `limb1`: bits 64–127
 * - `limb2`: bits 128–191
 * - `limb3`: bits 192–255 (most significant)
 *
 * The reconstruction formula is:
 * ```
 * value = limb0 + limb1 * 2^64 + limb2 * 2^128 + limb3 * 2^192
 * ```
 *
 * ## Montgomery Multiplication
 *
 * Multiplication uses the CIOS (Coarsely Integrated Operand Scanning) variant of
 * Montgomery multiplication. Working in "Montgomery domain" (where each value `a`
 * is stored as `aR mod p` for `R = 2^256`) allows the inner multiplication-and-reduction
 * loop to avoid a full division by `p`. Instead, it uses a precomputed constant
 * `p' = -p^(-1) mod 2^64` to make each output limb divisible by `2^64`, enabling
 * a right-shift instead of a division.
 *
 * @see {@link ./types} BN254 field element types and validation
 * @see {@link ./operations} Higher-level field operations (non-constant-time)
 * @see {@link ./interfaces} Function type interfaces implemented here
 * @see {@link ./field-element-sampler} Sampler that depends on this module
 *
 * @packageDocumentation
 * @module math/bn254/field-arithmetic
 */

import type {
  Bn254FieldElementLimb,
  ModuloAddFunction as ModuleAddFunction,
  ModuloInvFunction as ModuleInvFunction,
  ModuloMulFunction as ModuleMulFunction,
  ModuloNegFunction as ModuleNegFunction,
  ModuloSubFunction as ModuleSubFunction,
} from "./interfaces";
import { type Bn254FieldElement, BN254_FIELD_PRIME, assertBn254FieldElement } from "./types";
import type { Base85LimbTuple } from "../../crypto/poseidon/types";

// =============================================================================
// Constants
// =============================================================================

/**
 * Number of bits per 64-bit limb, as a `bigint` for use in shift operations.
 *
 * @remarks
 * All bit-shift operations in this module use `bigint` arithmetic, so `N64 = 64n`
 * avoids repeated `BigInt(64)` conversions. This is used in `bigintToLimbs`,
 * `limbsToBigint`, `addModuleLimbs`, `subModuleLimbs`, and `montgomeryMulLimbs`.
 *
 * @internal
 */
const N64 = 64n;

/**
 * Bit mask for extracting the lower 64 bits of a `bigint`.
 *
 * @remarks
 * Equal to `2^64 - 1 = 0xFFFFFFFFFFFFFFFF`. Applied via bitwise AND (`& MASK64`)
 * after additions and multiplications that may produce values wider than 64 bits,
 * to isolate the current limb value and separate it from any carry.
 *
 * @internal
 */
const MASK64 = 0xff_ff_ff_ff_ff_ff_ff_ffn;

/**
 * The BN254 scalar field prime `p` in 4-limb little-endian representation.
 *
 * @remarks
 * The prime is:
 * `p = 21888242871839275222246405745257275088548364400416034343698204186575808495617`
 * In hexadecimal: `0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001`
 *
 * Decomposed into four 64-bit little-endian limbs:
 * - `P_LIMBS[0] = 0x43e1f593f0000001` — bits 0–63
 * - `P_LIMBS[1] = 0x2833e84879b97091` — bits 64–127
 * - `P_LIMBS[2] = 0xb85045b68181585d` — bits 128–191
 * - `P_LIMBS[3] = 0x30644e72e131a029` — bits 192–255
 *
 * This constant is referenced in every limb-level operation: addition (trial subtraction),
 * subtraction (correction add), Montgomery reduction (multiplication by `m * p`), and
 * negation (`p - a`).
 *
 * @internal
 */
const P_LIMBS: Bn254FieldElementLimb = [
  0x43_e1_f5_93_f0_00_00_01n, // limb 0 (bits 0-63)
  0x28_33_e8_48_79_b9_70_91n, // limb 1 (bits 64-127)
  0xb8_50_45_b6_81_81_58_5dn, // limb 2 (bits 128-191)
  0x30_64_4e_72_e1_31_a0_29n, // limb 3 (bits 192-255)
];

/**
 * The Montgomery constant `p' = -p^(-1) mod 2^64`.
 *
 * @remarks
 * This constant is the core of the Montgomery reduction step. After accumulating
 * partial products in the CIOS loop, the reduction computes:
 * ```
 * m = (t[i] * P_PRIME) mod 2^64
 * ```
 * and then adds `m * p` to the accumulator, making `t[i]` divisible by `2^64`.
 * The key property is:
 * ```
 * p0 * P_PRIME ≡ -1  (mod 2^64)
 * ```
 * where `p0 = P_LIMBS[0] = 0x43e1f593f0000001` is the least significant limb of `p`.
 *
 * Value: `0xc2e1f593effffffF`
 *
 * This was derived using the Extended Euclidean Algorithm:
 * ```
 * P_PRIME = modular_inverse(p0, 2^64) negated mod 2^64
 * ```
 *
 * @privateRemarks
 * The formula is sometimes written as `mu = -p^(-1) mod b` where `b = 2^64`.
 * Since `p * P_PRIME ≡ -1 (mod 2^64)`, we have `p * (-P_PRIME) ≡ 1 (mod 2^64)`,
 * confirming that `P_PRIME` is indeed the negated modular inverse of `p` (mod 2^64).
 *
 * @internal
 */
const P_PRIME = 0xc2_e1_f5_93_ef_ff_ff_ffn;

/**
 * The value `R^2 mod p` for converting standard-form values to Montgomery form.
 *
 * @remarks
 * In Montgomery arithmetic with modulus `p` and Montgomery constant `R = 2^256`:
 * - The Montgomery form of `a` is `aR mod p`.
 * - Conversion from standard form uses: `toMontgomery(a) = MontMul(a, R^2 mod p)`
 *
 * Because `MontMul(a, R^2) = a * R^2 * R^(-1) mod p = aR mod p`, multiplying by
 * the precomputed constant `R^2 mod p` (via a single Montgomery multiplication)
 * achieves the conversion without a full multi-precision division.
 *
 * `R^2 mod p = (2^256)^2 mod p = 2^512 mod p`
 *
 * Stored in 4-limb little-endian form:
 * - `R2_LIMBS[0] = 0x1bb8e645ae216da7`
 * - `R2_LIMBS[1] = 0x53fe3ab1e35c59e3`
 * - `R2_LIMBS[2] = 0x8c49833d53bb8085`
 * - `R2_LIMBS[3] = 0x0216d0b17f4e44a5`
 *
 * @internal
 */
const R2_LIMBS: Bn254FieldElementLimb = [
  0x1b_b8_e6_45_ae_21_6d_a7n,
  0x53_fe_3a_b1_e3_5c_59_e3n,
  0x8c_49_83_3d_53_bb_80_85n,
  0x02_16_d0_b1_7f_4e_44_a5n,
];

/**
 * The value `1` in Montgomery domain, i.e., `R mod p = 2^256 mod p`.
 *
 * @remarks
 * The multiplicative identity element in the Montgomery domain is not `1` but
 * `R mod p`. When Montgomery exponentiation initializes the result accumulator to
 * "1", it must use this Montgomery-form representation.
 *
 * `ONE_MONT = R mod p = 2^256 mod p`
 *
 * Stored in 4-limb little-endian form:
 * - `ONE_MONT[0] = 0xac96341c4ffffffb`
 * - `ONE_MONT[1] = 0x36fc76959f60cd29`
 * - `ONE_MONT[2] = 0x666ea36f7879462e`
 * - `ONE_MONT[3] = 0x0e0a77c19a07df2f`
 *
 * @internal
 */
const ONE_MONT: Bn254FieldElementLimb = [
  0xac_96_34_1c_4f_ff_ff_fbn,
  0x36_fc_76_95_9f_60_cd_29n,
  0x66_6e_a3_6f_78_79_46_2en,
  0x0e_0a_77_c1_9a_07_df_2fn,
];

// =============================================================================
// Internal Helper Functions
// =============================================================================

/**
 * Performs a constant-time conditional select between two `bigint` values.
 *
 * Returns `x` if `bit === 1n`, or `y` if `bit === 0n`, using bitwise masking
 * to avoid any data-dependent branch.
 *
 * @remarks
 * ## Implementation
 *
 * JavaScript's `bigint` supports arbitrary-precision two's complement. For `bit`:
 * - `bit === 1n` → `mask = -1n` (infinite sequence of set bits) → `(x & mask) | (y & ~mask) = x | 0 = x`
 * - `bit === 0n` → `mask = 0n` (no bits set) → `(x & mask) | (y & ~mask) = 0 | y = y`
 *
 * This idiom is used throughout the limb-arithmetic functions wherever a conditional
 * selection must occur without branching.
 *
 * @param bit - Selection bit. Must be exactly `0n` or `1n`. Passing any other value
 *   yields undefined results.
 * @param x - The value returned when `bit === 1n`.
 * @param y - The value returned when `bit === 0n`.
 * @returns `x` if `bit === 1n`; `y` otherwise.
 *
 * @example
 * ```typescript
 * // Internal usage — always branch-free:
 * const borrow = 1n; // pretend subtraction underflowed
 * const corrected = ctSelect(borrow, original + P, original);
 * // equivalent to: borrow ? original + P : original
 * ```
 *
 * @internal
 */
function ctSelect(bit: bigint, x: bigint, y: bigint): bigint {
  // If bit is 1, mask is all 1s (-1n in two's complement)
  // If bit is 0, mask is 0n
  const mask = -bit;
  return (x & mask) | (y & ~mask);
}

/**
 * Converts a `bigint` to a 4-element little-endian 64-bit limb tuple.
 *
 * @remarks
 * Each element of the output holds exactly 64 bits of the input:
 * ```
 * output[k] = (value >> (64 * k)) & MASK64
 * ```
 * Bits above position 255 are silently truncated. The input should be
 * in `[0, 2^256 - 1]` for meaningful results.
 *
 * @param value - The `bigint` to decompose. Should satisfy `0 <= value < 2^256`.
 * @returns A 4-tuple `[limb0, limb1, limb2, limb3]` in little-endian order,
 *   each limb in `[0, 2^64 - 1]`.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * bigintToLimbs(1n);         // [1n, 0n, 0n, 0n]
 * bigintToLimbs(2n ** 64n);  // [0n, 1n, 0n, 0n]
 * bigintToLimbs(2n ** 128n); // [0n, 0n, 1n, 0n]
 * ```
 *
 * @internal
 */
function bigintToLimbs(value: bigint): Bn254FieldElementLimb {
  return [
    value & MASK64,
    (value >> N64) & MASK64,
    (value >> (N64 * 2n)) & MASK64,
    (value >> (N64 * 3n)) & MASK64,
  ];
}

/**
 * Reconstructs a `bigint` from a 4-element little-endian 64-bit limb tuple.
 *
 * @remarks
 * Applies the positional formula:
 * ```
 * value = limbs[0] + limbs[1] * 2^64 + limbs[2] * 2^128 + limbs[3] * 2^192
 * ```
 * The result is in `[0, 2^256 - 1]` when all limbs are in `[0, 2^64 - 1]`.
 * This is the exact inverse of `bigintToLimbs`.
 *
 * @param limbs - A 4-tuple `[limb0, limb1, limb2, limb3]` in little-endian order.
 * @returns The reconstructed `bigint` value.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * limbsToBigint([1n, 0n, 0n, 0n]);  // 1n
 * limbsToBigint([0n, 1n, 0n, 0n]);  // 2^64
 * limbsToBigint([0n, 0n, 0n, 1n]);  // 2^192
 * ```
 *
 * @internal
 */
function limbsToBigint(limbs: Bn254FieldElementLimb): bigint {
  return limbs[0] + (limbs[1] << N64) + (limbs[2] << (N64 * 2n)) + (limbs[3] << (N64 * 3n));
}

/**
 * Computes `(a + b) mod p` on 4-limb representations using constant-time arithmetic.
 *
 * @remarks
 * ## Algorithm
 *
 * 1. **Raw addition** with carry propagation across all 4 limbs. The final carry
 *    (`tCarry`) is `1n` if the sum `a + b` exceeded `2^256 - 1`, `0n` otherwise.
 * 2. **Trial subtraction** of `p` with borrow propagation across all 4 limbs.
 *    The final borrow (`borrow`) is `1n` if `(a + b) < p` (no reduction needed),
 *    `0n` if `(a + b) >= p` (reduction needed).
 * 3. **Constant-time selection**:
 *    - If `tCarry === 1n` (sum overflowed 256 bits), the sum is definitely `>= p`,
 *      so use the subtracted result `d`.
 *    - Otherwise, if `borrow === 0n` (no underflow in trial subtraction), the sum
 *      is `>= p`, so use `d`.
 *    - If `borrow === 1n` and `tCarry === 0n`, the sum is `< p`, so keep `t`.
 *    The combined condition `useD = tCarry | (1n - borrow)` covers both cases.
 *
 * @param a - First operand in 4-limb form, representing a value in `[0, p-1]`.
 * @param b - Second operand in 4-limb form, representing a value in `[0, p-1]`.
 * @returns The sum `(a + b) mod p` in 4-limb form.
 *
 * @example
 * ```typescript
 * // Internal usage (all via bigintToLimbs/limbsToBigint wrapper in bn254ModuloAdd):
 * const aLimbs = bigintToLimbs(BN254_FIELD_PRIME - 1n);
 * const bLimbs = bigintToLimbs(2n);
 * const result = addModuleLimbs(aLimbs, bLimbs);
 * limbsToBigint(result); // 1n (wrapped around)
 * ```
 *
 * @internal
 */
function addModuleLimbs(a: Bn254FieldElementLimb, b: Bn254FieldElementLimb): Bn254FieldElementLimb {
  // 1. Raw Addition: t = a + b
  const t: bigint[] = [0n, 0n, 0n, 0n];
  let carry = 0n;

  for (let index = 0; index < 4; index++) {
    const sum = a[index] + b[index] + carry;
    t[index] = sum & MASK64;
    carry = sum >> N64;
  }
  const tCarry = carry; // 1n if a+b overflowed 256 bits

  // 2. Trial Subtraction: d = t - p
  const d: bigint[] = [0n, 0n, 0n, 0n];
  let borrow = 0n;

  for (let index = 0; index < 4; index++) {
    const sub = t[index] - P_LIMBS[index] - borrow;
    d[index] = sub & MASK64;
    borrow = -(sub >> N64); // 1n if borrowed, 0n otherwise
  }

  // 3. Selection
  // Use d if: addition overflowed (tCarry == 1) OR subtraction didn't underflow (borrow == 0)
  const useD = tCarry | (1n - borrow);

  return [
    ctSelect(useD, d[0], t[0]),
    ctSelect(useD, d[1], t[1]),
    ctSelect(useD, d[2], t[2]),
    ctSelect(useD, d[3], t[3]),
  ];
}

/**
 * Computes `(a - b) mod p` on 4-limb representations using constant-time arithmetic.
 *
 * @remarks
 * ## Algorithm
 *
 * 1. **Raw subtraction** `diff = a - b` with borrow propagation across all 4 limbs.
 *    The final borrow is `1n` if `a < b` (underflow occurred), `0n` if `a >= b`.
 * 2. **Conditional correction**: if `borrow === 1n`, add `p` back to the result
 *    to wrap around correctly. The addition of `p` is applied via a bitmask derived
 *    from `borrow`: `mask = -borrow` (all 1s if borrow, all 0s otherwise). Each
 *    limb of `p` is AND-masked before being added, so the addition only occurs
 *    when there was an underflow.
 *
 * @param a - Minuend in 4-limb form, representing a value in `[0, p-1]`.
 * @param b - Subtrahend in 4-limb form, representing a value in `[0, p-1]`.
 * @returns The difference `(a - b) mod p` in 4-limb form.
 *
 * @example
 * ```typescript
 * // Internal usage:
 * const aLimbs = bigintToLimbs(5n);
 * const bLimbs = bigintToLimbs(10n);
 * const result = subModuleLimbs(aLimbs, bLimbs);
 * limbsToBigint(result); // BN254_FIELD_PRIME - 5n
 * ```
 *
 * @internal
 */
function subModuleLimbs(a: Bn254FieldElementLimb, b: Bn254FieldElementLimb): Bn254FieldElementLimb {
  // 1. Calculate diff = a - b
  const out: bigint[] = [0n, 0n, 0n, 0n];
  let borrow = 0n;

  for (let index = 0; index < 4; index++) {
    const sub = a[index] - b[index] - borrow;
    out[index] = sub & MASK64;
    borrow = -(sub >> N64); // 1n if underflow happened
  }

  // 2. If we borrowed, add P back using masking
  const mask = -borrow;
  let carry = 0n;

  for (let index = 0; index < 4; index++) {
    const addValue = P_LIMBS[index] & mask;

    const sum = out[index] + addValue + carry;
    out[index] = sum & MASK64;
    carry = sum >> N64;
  }

  return [out[0], out[1], out[2], out[3]];
}

/**
 * Computes `(a * b * R^(-1)) mod p` using the CIOS (Coarsely Integrated Operand
 * Scanning) Montgomery multiplication algorithm on 4-limb representations.
 *
 * @remarks
 * ## Montgomery Multiplication Background
 *
 * Montgomery multiplication computes `MontMul(a, b) = a * b * R^(-1) mod p`,
 * where `R = 2^256`. When `a` and `b` are both in Montgomery form (`a = x * R mod p`
 * and `b = y * R mod p`), the result is:
 * ```
 * MontMul(xR, yR) = xR * yR * R^(-1) mod p = xyR mod p
 * ```
 * which is also in Montgomery form. This makes Montgomery multiplication closed
 * under composition: chains of multiplications stay in the Montgomery domain.
 *
 * ## CIOS Algorithm
 *
 * The CIOS variant integrates the multiplication and reduction into a single loop:
 * for each limb `i` of `a`:
 * 1. Accumulate partial products: `t += a[i] * b` (inner 4-limb loop with carry)
 * 2. Compute the Montgomery reduction factor: `m = (t[i] * P_PRIME) mod 2^64`
 * 3. Eliminate the lowest accumulated limb: add `m * p` to `t` (inner 4-limb loop),
 *    which makes `t[i]` divisible by `2^64` and can be discarded
 *
 * After 4 outer iterations, the 512-bit accumulator `t` holds `a * b * R^(-1) mod p`
 * in its upper 256 bits (`t[4]...t[7]`). A final conditional subtraction reduces
 * this to `[0, p-1]`.
 *
 * ## Why Montgomery?
 *
 * The naive `(a * b) % p` requires a multi-precision division by `p`, which has
 * variable execution time. Montgomery reduction replaces the division with a
 * multiply-and-shift, enabling constant-operation-count multiplication.
 *
 * @param a - First factor in Montgomery form (4-limb little-endian, value `xR mod p`).
 * @param b - Second factor in Montgomery form (4-limb little-endian, value `yR mod p`).
 * @returns The Montgomery product `(a * b * R^(-1)) mod p` in 4-limb form.
 *
 * @example
 * ```typescript
 * // Internal usage (not called directly; use bn254ModuloMul instead):
 * const aM = toMontgomery(bigintToLimbs(7n));
 * const bM = toMontgomery(bigintToLimbs(8n));
 * const productM = montgomeryMulLimbs(aM, bM);
 * const product = limbsToBigint(fromMontgomery(productM)); // 56n
 * ```
 *
 * @internal
 */
function montgomeryMulLimbs(
  a: Bn254FieldElementLimb,
  b: Bn254FieldElementLimb,
): Bn254FieldElementLimb {
  // Accumulator array (9 limbs: 8 for 512-bit intermediate + 1 for carry overflow)
  const t: bigint[] = [0n, 0n, 0n, 0n, 0n, 0n, 0n, 0n, 0n];

  for (let index = 0; index < 4; index++) {
    // 1. Inner loop: t = t + a[i] * b
    let carry = 0n;
    for (let innerIndex = 0; innerIndex < 4; innerIndex++) {
      const sum = t[index + innerIndex] + a[index] * b[innerIndex] + carry;
      t[index + innerIndex] = sum & MASK64;
      carry = sum >> N64;
    }
    t[index + 4] = t[index + 4] + carry;

    // 2. Montgomery reduction step
    // m = (t[i] * p_prime) mod 2^64
    const m = (t[index] * P_PRIME) & MASK64;

    // Add m * p to t (this makes t[i] divisible by 2^64)
    let carryRed = 0n;
    for (let innerIndex = 0; innerIndex < 4; innerIndex++) {
      const sum = t[index + innerIndex] + m * P_LIMBS[innerIndex] + carryRed;
      t[index + innerIndex] = sum & MASK64;
      carryRed = sum >> N64;
    }

    // Propagate carry
    const sumUp = t[index + 4] + carryRed;
    t[index + 4] = sumUp & MASK64;
    t[index + 5] = t[index + 5] + (sumUp >> N64);
  }

  // Result is in t[4]...t[7]
  const result: bigint[] = [t[4], t[5], t[6], t[7]];

  // Conditional subtraction if result >= p
  const subResult: bigint[] = [0n, 0n, 0n, 0n];
  let borrow = 0n;
  for (let k = 0; k < 4; k++) {
    const s = result[k] - P_LIMBS[k] - borrow;
    subResult[k] = s & MASK64;
    borrow = -(s >> N64);
  }

  // If borrow is 0, result >= p, so use subResult
  // If borrow is 1, result < p, so keep result
  const useSub = 1n - borrow;

  return [
    ctSelect(useSub, subResult[0], result[0]),
    ctSelect(useSub, subResult[1], result[1]),
    ctSelect(useSub, subResult[2], result[2]),
    ctSelect(useSub, subResult[3], result[3]),
  ];
}

/**
 * Converts a field element from standard form to Montgomery form: `a -> aR mod p`.
 *
 * @remarks
 * Computed as `MontMul(a, R^2 mod p)`:
 * ```
 * toMontgomery(a) = MontMul(a, R^2) = a * R^2 * R^(-1) mod p = a * R mod p
 * ```
 * where the precomputed `R2_LIMBS` constant holds `R^2 mod p = 2^512 mod p`.
 *
 * This conversion must be performed before any Montgomery multiplication. After
 * conversion, all field arithmetic happens in the Montgomery domain until the
 * final result is converted back via `fromMontgomery`.
 *
 * @param a - A field element in standard form (4-limb, value `a` in `[0, p-1]`).
 * @returns The Montgomery form `aR mod p` in 4-limb representation.
 *
 * @example
 * ```typescript
 * // Internal usage in bn254ModuloMul:
 * const aM = toMontgomery(bigintToLimbs(7n));
 * // aM now represents 7 * R mod p in the Montgomery domain
 * ```
 *
 * @internal
 */
function toMontgomery(a: Bn254FieldElementLimb): Bn254FieldElementLimb {
  return montgomeryMulLimbs(a, R2_LIMBS);
}

/**
 * Converts a field element from Montgomery form back to standard form: `aR -> a mod p`.
 *
 * @remarks
 * Computed as `MontMul(aR, 1)` where `1` is the standard (non-Montgomery) integer 1:
 * ```
 * fromMontgomery(aR) = MontMul(aR, 1) = aR * 1 * R^(-1) mod p = a mod p
 * ```
 * The standard-form `1` is the limb tuple `[1n, 0n, 0n, 0n]`.
 *
 * @param a - A field element in Montgomery form (4-limb, value `aR mod p`).
 * @returns The standard form `a mod p` in 4-limb representation.
 *
 * @example
 * ```typescript
 * // Internal usage in bn254ModuloMul:
 * const aM = toMontgomery(bigintToLimbs(7n));
 * const bM = toMontgomery(bigintToLimbs(8n));
 * const productM = montgomeryMulLimbs(aM, bM);
 * const product = fromMontgomery(productM);
 * limbsToBigint(product); // 56n
 * ```
 *
 * @internal
 */
function fromMontgomery(a: Bn254FieldElementLimb): Bn254FieldElementLimb {
  // Multiply by 1 (in standard limb form, not Montgomery form)
  const one: Bn254FieldElementLimb = [1n, 0n, 0n, 0n];
  return montgomeryMulLimbs(a, one);
}

/**
 * Computes the additive inverse `-a mod p` in 4-limb representation.
 *
 * @remarks
 * ## Algorithm
 *
 * The additive inverse of `a` is `p - a` when `a != 0`, and `0` when `a == 0`.
 * The zero check is performed in constant time by OR-ing all limbs:
 * ```
 * isZero = (a[0] | a[1] | a[2] | a[3]) === 0n ? 1n : 0n
 * ```
 * The subtraction `p - a` is computed unconditionally via `subModuleLimbs(P_LIMBS, a)`.
 * The final result is then selected using `ctSelect`:
 * - If `isZero === 1n`: return `[0n, 0n, 0n, 0n]`
 * - If `isZero === 0n`: return `p - a`
 *
 * @param a - The field element to negate, in 4-limb form, value in `[0, p-1]`.
 * @returns The negation `-a mod p` in 4-limb form.
 *
 * @example
 * ```typescript
 * // Internal usage in bn254ModuloNeg:
 * const aLimbs = bigintToLimbs(10n);
 * const negLimbs = negModuleLimbs(aLimbs);
 * limbsToBigint(negLimbs); // BN254_FIELD_PRIME - 10n
 *
 * const zeroLimbs = bigintToLimbs(0n);
 * const negZero = negModuleLimbs(zeroLimbs);
 * limbsToBigint(negZero); // 0n
 * ```
 *
 * @internal
 */
function negModuleLimbs(a: Bn254FieldElementLimb): Bn254FieldElementLimb {
  // Check if a is zero (constant-time)
  const isZero = (a[0] | a[1] | a[2] | a[3]) === 0n ? 1n : 0n;

  // Compute p - a
  const result = subModuleLimbs(P_LIMBS, a);

  // If a was zero, return zero; else return p - a
  return [
    ctSelect(isZero, 0n, result[0]),
    ctSelect(isZero, 0n, result[1]),
    ctSelect(isZero, 0n, result[2]),
    ctSelect(isZero, 0n, result[3]),
  ];
}

/**
 * Computes `base^exp mod p` using the square-and-multiply algorithm entirely in
 * the Montgomery domain.
 *
 * @remarks
 * ## Algorithm: Square-and-Multiply in Montgomery Domain
 *
 * 1. Initialize `result = ONE_MONT` (the Montgomery form of `1`, i.e., `R mod p`).
 * 2. For each bit of `exp` from least significant to most significant:
 *    - If the bit is set: `result = MontMul(result, current)`
 *    - Square: `current = MontMul(current, current)`
 * 3. Return `result`, which is `base^exp * R mod p` in Montgomery form.
 *    The caller (`bn254ModuloInv`) converts back via `fromMontgomery`.
 *
 * ## Note on Constant Time
 *
 * This function branches on bits of `exp`. When `exp = p - 2` (for Fermat inversion),
 * `p` is a public constant, so leaking bits of `exp` via timing does NOT compromise
 * secret data. The branching is therefore acceptable.
 *
 * @param base - The base in Montgomery form (4-limb, value `base * R mod p`).
 * @param exp - The exponent as a `bigint` (standard non-negative integer, not in Montgomery form).
 * @returns `base^exp * R mod p` in 4-limb Montgomery form.
 *
 * @example
 * ```typescript
 * // Internal usage in bn254ModuloInv:
 * const aM = toMontgomery(bigintToLimbs(7n));
 * const invM = moduleExpMontgomery(aM, BN254_FIELD_PRIME - 2n);
 * const inv = fromMontgomery(invM);
 * limbsToBigint(inv); // 7^(-1) mod p
 * ```
 *
 * @internal
 */
function moduleExpMontgomery(base: Bn254FieldElementLimb, exp: bigint): Bn254FieldElementLimb {
  let result = ONE_MONT; // 1 in Montgomery form
  let current = base;

  while (exp > 0n) {
    if ((exp & 1n) === 1n) {
      result = montgomeryMulLimbs(result, current);
    }
    current = montgomeryMulLimbs(current, current);
    exp >>= 1n;
  }

  return result;
}

