/**
 * Constant-time modular addition over the BN254 scalar field.
 *
 * Computes `(a + b) mod p` where `p = BN254_FIELD_PRIME`.
 *
 * @param a - First addend. Must be in the canonical range `[0, p-1]`.
 * @param b - Second addend. Must be in the canonical range `[0, p-1]`.
 * @returns The sum `(a + b) mod p` in the canonical range `[0, p-1]`.
 *
 * @remarks
 * This is the production constant-time implementation of `ModuloAddFunction`.
 * Internally, it converts both inputs to 4-limb form, runs `addModuleLimbs`
 * (which performs carry propagation and a conditional trial subtraction),
 * and reconstructs the output bigint.
 *
 * The function processes all 4 limbs uniformly with no early exit, ensuring
 * constant-operation-count execution.
 *
 * @example
 * ```typescript
 * import { bn254ModuloAdd, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Basic addition
 * const sum = bn254ModuloAdd(10n, 20n); // 30n
 *
 * // Wrap-around at the field boundary
 * const nearPrime = BN254_FIELD_PRIME - 1n;
 * const wrapped = bn254ModuloAdd(nearPrime, 2n); // 1n
 *
 * // Additive identity
 * const identity = bn254ModuloAdd(42n, 0n); // 42n
 * ```
 *
 * @see {@link getBn254ModularAdder} Cached getter for this function
 * @see {@link bn254ModuloSub} For modular subtraction
 * @see {@link ModuloAddFunction} The interface type this satisfies
 *
 * @public
 */
export const bn254ModuloAdd: ModuleAddFunction = (a: bigint, b: bigint): bigint => {
  const aLimbs = bigintToLimbs(a);
  const bLimbs = bigintToLimbs(b);
  const resultLimbs = addModuleLimbs(aLimbs, bLimbs);
  return limbsToBigint(resultLimbs);
};

/**
 * Constant-time modular subtraction over the BN254 scalar field.
 *
 * Computes `(a - b) mod p` where `p = BN254_FIELD_PRIME`.
 *
 * @param a - Minuend. Must be in the canonical range `[0, p-1]`.
 * @param b - Subtrahend. Must be in the canonical range `[0, p-1]`.
 * @returns The difference `(a - b) mod p` in the canonical range `[0, p-1]`.
 *
 * @remarks
 * This is the production constant-time implementation of `ModuloSubFunction`.
 * Internally, it converts both inputs to 4-limb form, runs `subModuleLimbs`
 * (raw subtraction with borrow propagation followed by conditional addition of `p`),
 * and reconstructs the output bigint.
 *
 * When `a < b`, the result wraps around by adding `p`, giving `p - (b - a)`.
 *
 * @example
 * ```typescript
 * import { bn254ModuloSub, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Basic subtraction
 * const diff = bn254ModuloSub(30n, 10n); // 20n
 *
 * // Underflow wraps around the field boundary
 * const wrapped = bn254ModuloSub(5n, 10n); // BN254_FIELD_PRIME - 5n
 *
 * // Self-subtraction gives zero
 * const zero = bn254ModuloSub(42n, 42n); // 0n
 * ```
 *
 * @see {@link getBn254ModularSubtractor} Cached getter for this function
 * @see {@link bn254ModuloAdd} For modular addition
 * @see {@link bn254ModuloNeg} For modular negation
 * @see {@link ModuloSubFunction} The interface type this satisfies
 *
 * @public
 */
export const bn254ModuloSub: ModuleSubFunction = (a: bigint, b: bigint): bigint => {
  const aLimbs = bigintToLimbs(a);
  const bLimbs = bigintToLimbs(b);
  const resultLimbs = subModuleLimbs(aLimbs, bLimbs);
  return limbsToBigint(resultLimbs);
};

/**
 * Constant-time modular multiplication over the BN254 scalar field using
 * Montgomery multiplication.
 *
 * Computes `(a * b) mod p` where `p = BN254_FIELD_PRIME`.
 *
 * @param a - First factor. Must be in the canonical range `[0, p-1]`.
 * @param b - Second factor. Must be in the canonical range `[0, p-1]`.
 * @returns The product `(a * b) mod p` in the canonical range `[0, p-1]`.
 *
 * @remarks
 * This is the production constant-time implementation of `ModuloMulFunction`.
 * It performs three Montgomery operations:
 * 1. `toMontgomery(a)` — convert `a` to Montgomery form
 * 2. `toMontgomery(b)` — convert `b` to Montgomery form
 * 3. `montgomeryMulLimbs(aM, bM)` — multiply in Montgomery domain
 * 4. `fromMontgomery(resultM)` — convert result back to standard form
 *
 * ## Performance Note
 *
 * Each Montgomery conversion internally calls `montgomeryMulLimbs`, so the total
 * cost is 3 Montgomery multiplications per call to `bn254ModuloMul`. This is
 * acceptable for correctness and security, but for performance-critical paths
 * (e.g., exponentiation), consider keeping values in Montgomery form throughout
 * and only converting back at the end.
 *
 * @example
 * ```typescript
 * import { bn254ModuloMul, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * // Basic multiplication
 * const product = bn254ModuloMul(7n, 8n); // 56n
 *
 * // All results reduced mod p
 * const large = bn254ModuloMul(BN254_FIELD_PRIME - 1n, 2n); // p - 2n
 *
 * // Multiplicative identity
 * const identity = bn254ModuloMul(42n, 1n); // 42n
 * ```
 *
 * @see {@link getBn254ModularMultiplier} Cached getter for this function
 * @see {@link bn254ModuloInv} For multiplicative inverse
 * @see {@link ModuloMulFunction} The interface type this satisfies
 *
 * @public
 */
export const bn254ModuloMul: ModuleMulFunction = (a: bigint, b: bigint): bigint => {
  const aLimbs = bigintToLimbs(a);
  const bLimbs = bigintToLimbs(b);

  // Convert to Montgomery form
  const aMont = toMontgomery(aLimbs);
  const bMont = toMontgomery(bLimbs);

  // Multiply in Montgomery form
  const resultMont = montgomeryMulLimbs(aMont, bMont);

  // Convert back from Montgomery form
  const resultLimbs = fromMontgomery(resultMont);

  return limbsToBigint(resultLimbs);
};

/**
 * Constant-time modular negation over the BN254 scalar field.
 *
 * Computes `-a mod p`, equal to `p - a` for non-zero `a`, and `0` for `a == 0`.
 *
 * @param a - The value to negate. Must be in the canonical range `[0, p-1]`.
 * @returns `-a mod p` in the canonical range `[0, p-1]`.
 *
 * @remarks
 * This is the production constant-time implementation of `ModuloNegFunction`.
 * Internally, it converts the input to 4-limb form and calls `negModuleLimbs`,
 * which:
 * 1. Detects zero via bitwise OR of all limbs (constant-time zero check)
 * 2. Unconditionally computes `p - a` via `subModuleLimbs(P_LIMBS, a)`
 * 3. Selects `0` or `p - a` using `ctSelect` based on the zero flag
 *
 * @example
 * ```typescript
 * import { bn254ModuloNeg, bn254ModuloAdd, BN254_FIELD_PRIME } from "@umbra/sdk";
 *
 * const a = 10n;
 * const negA = bn254ModuloNeg(a); // BN254_FIELD_PRIME - 10n
 *
 * // Verify: a + (-a) = 0 (mod p)
 * const sum = bn254ModuloAdd(a, negA); // 0n
 *
 * // Negation of zero is zero
 * console.log(bn254ModuloNeg(0n) === 0n); // true
 * ```
 *
 * @see {@link getBn254ModularNegator} Cached getter for this function
 * @see {@link bn254ModuloSub} Subtraction as a + (-b)
 * @see {@link ModuloNegFunction} The interface type this satisfies
 *
 * @public
 */
export const bn254ModuloNeg: ModuleNegFunction = (a: bigint): bigint => {
  const aLimbs = bigintToLimbs(a);
  const resultLimbs = negModuleLimbs(aLimbs);
  return limbsToBigint(resultLimbs);
};

/**
 * Constant-time modular multiplicative inverse over the BN254 scalar field
 * using Fermat's Little Theorem and Montgomery exponentiation.
 *
 * Computes `a^(-1) mod p` such that `a * a^(-1) ≡ 1 (mod p)`.
 *
 * @param a - The value to invert. Must be non-zero and in `[1, p-1]`.
 * @returns `a^(-1) mod p` in the canonical range `[1, p-1]`.
 * @throws {Error} If `a === 0n`, since zero has no multiplicative inverse.
 *
 * @remarks
 * This is the production implementation of `ModuloInvFunction`.
 *
 * ## Algorithm
 *
 * By Fermat's Little Theorem: `a^(p-1) ≡ 1 (mod p)` for prime `p` and `a != 0`.
 * Therefore: `a^(-1) ≡ a^(p-2) (mod p)`.
 *
 * This function computes `a^(p-2) mod p` via:
 * 1. Convert `a` to Montgomery form: `aM = toMontgomery(a)`
 * 2. Compute `aM^(p-2)` via `moduleExpMontgomery(aM, p-2)` (square-and-multiply)
 * 3. Convert back: `inv = fromMontgomery(resultM)`
 *
 * ## Complexity
 *
 * The exponent `p - 2` has 254 bits. The square-and-multiply algorithm requires
 * at most 254 squarings and at most 254 multiplications (one per set bit).
 * Each Montgomery multiplication is O(4^2) = O(16) 64-bit operations plus
 * carry/borrow propagation.
 *
 * ## Zero Handling
 *
 * An explicit zero check is performed before entering the Montgomery path.
 * This is an early branch on `a === 0n` (the *public* exceptional case), so
 * it does not leak timing information about secret inputs (unless the caller
 * passes a secret zero, which would be a protocol error).
 *
 * @example
 * ```typescript
 * import { bn254ModuloInv, bn254ModuloMul } from "@umbra/sdk";
 *
 * const a = 7n;
 * const invA = bn254ModuloInv(a);
 *
 * // Verify: a * a^(-1) = 1 (mod p)
 * const product = bn254ModuloMul(a, invA); // 1n
 *
 * // Division: 42 / 7 = 6 (mod p)
 * const quotient = bn254ModuloMul(42n, invA); // 6n
 *
 * // This throws:
 * bn254ModuloInv(0n); // Error: Cannot compute modular inverse of zero
 * ```
 *
 * @see {@link getBn254ModularInverter} Cached getter for this function
 * @see {@link bn254ModuloMul} For multiplication (use to verify the inverse)
 * @see {@link ModuloInvFunction} The interface type this satisfies
 * @see {@link computeBn254LimbwiseSumInverse} For inverting a Base85 limb sum
 *
 * @public
 */
export const bn254ModuloInv: ModuleInvFunction = (a: bigint): bigint => {
  if (a === 0n) {
    throw new Error("Cannot compute modular inverse of zero");
  }

  const aLimbs = bigintToLimbs(a);

  // Convert to Montgomery form
  const aMont = toMontgomery(aLimbs);

  // Compute a^(p-2) in Montgomery form using Fermat's Little Theorem
  const exp = BN254_FIELD_PRIME - 2n;
  const resultMont = moduleExpMontgomery(aMont, exp);

  // Convert back from Montgomery form
  const resultLimbs = fromMontgomery(resultMont);

  return limbsToBigint(resultLimbs);
};

