// =============================================================================

/**
 * Computes the modular multiplicative inverse of the sum of a `Base85LimbTuple`
 * in the BN254 scalar field.
 *
 * Given a `Base85LimbTuple` with fields `low`, `middle`, and `high`, computes:
 * ```
 * (low + middle + high)^(-1) mod p
 * ```
 *
 * @param limbs - A `Base85LimbTuple` containing three 85-bit limbs:
 *   `low` (bits 0–84), `middle` (bits 85–169), and `high` (bits 170–255).
 * @returns The modular inverse of the sum as a `Bn254FieldElement` in `[1, p-1]`.
 * @throws {Error} If the sum `low + middle + high ≡ 0 (mod p)`, meaning no
 *   multiplicative inverse exists.
 *
 * @remarks
 * ## Context: ZK Non-Zero Witness
 *
 * In Circom/Groth16 zero-knowledge circuits, proving that a value is non-zero
 * requires the prover to supply the multiplicative inverse of that value as an
 * auxiliary witness input. The circuit then verifies:
 * ```
 * value * witness_inv = 1
 * ```
 * which can only be satisfied if `value != 0`.
 *
 * For values represented as three 85-bit limbs (Base85 format, common in
 * Poseidon hash inputs), the circuit may require the inverse of the *sum of limbs*
 * rather than the inverse of the fully reconstructed value. This is because:
 * 1. If all limbs are zero, the full value is zero (and the sum is also zero).
 * 2. If any limb is non-zero, the sum is non-zero (given the limb range constraints).
 * 3. Computing the sum is cheaper in the circuit than the full positional reconstruction.
 *
 * ## Security
 *
 * The inversion is performed via `bn254ModuloInv`, which uses Fermat's Little Theorem
 * and Montgomery form — the same constant-time path as all other inversions in this
 * module.
 *
 * @example
 * ```typescript
 * import {
 *   computeBn254LimbwiseSumInverse,
 *   bn254ModuloMul,
 * } from "@umbra/sdk";
 * import { assertBase85Limb } from "@umbra/sdk";
 *
 * const low    = 1000n;
 * const middle = 2000n;
 * const high   = 3000n;
 * assertBase85Limb(low,    "low");
 * assertBase85Limb(middle, "middle");
 * assertBase85Limb(high,   "high");
 *
 * // Computes (1000 + 2000 + 3000)^(-1) mod p = 6000^(-1) mod p
 * const inverse = computeBn254LimbwiseSumInverse({ low, middle, high });
 *
 * // Verify: sum * inverse = 1 (mod p)
 * const sum = (low + middle + high) % BN254_FIELD_PRIME;
 * assertBn254FieldElement(sum);
 * const check = bn254ModuloMul(sum, inverse);
 * console.log(check === 1n); // true
 * ```
 *
 * @see {@link bn254ModuloInv} The underlying inversion function
 * @see {@link Base85LimbTuple} The input type from `crypto/poseidon/types`
 * @see {@link ./operations.computeBn254LimbwiseSumInverse} The non-CT version in `operations.ts`
 *
 * @public
 */
export function computeBn254LimbwiseSumInverse(limbs: Base85LimbTuple): Bn254FieldElement {
  // Sum the limbs (each limb is < 2^85, so sum fits well within bigint)
  const sum = (limbs.low + limbs.middle + limbs.high) % BN254_FIELD_PRIME;

  if (sum === 0n) {
    throw new Error(
      "Cannot compute modular inverse of zero sum. " + "The sum of Base85 limbs must be non-zero.",
    );
  }

  // Compute modular inverse using Fermat's Little Theorem
  const inverse = bn254ModuloInv(sum);

  assertBn254FieldElement(inverse);
  return inverse;
}
